function demoData(){const n=250,arr=[];let prev=71;for(let i=0;i<n;i++){const cyc=Math.sin(i/15)*7+Math.sin(i/33)*13;let close=69+i*.15+cyc+Math.sin(i*2.3)*2;close=Math.max(10,close);const open=prev, high=Math.max(open,close)+(1+Math.abs(Math.sin(i*1.5))*2),low=Math.min(open,close)-(1+Math.abs(Math.cos(i*2))*2);const d=new Date(today()+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-n+1+i);arr.push({date:d.toISOString().slice(0,10),open,high,low,close,volume:10000+i*10});prev=close;}const delta=state.lastDemoPrice-arr[arr.length-1].close;return arr.map((o,i)=>({...o,open:o.open+delta,high:o.high+delta,low:o.low+delta,close:o.close+delta}));}
