function position(symbol){let chunks=[],realized=0,hasTrade=false,currency=null,name=STOCK_NAMES[symbol]||symbol;const records=rowsFor(symbol);for(const t of records){hasTrade=true;currency=t.currency||currency;name=t.name||name;if(t.type==='buy'){chunks.push({q:+t.quantity,cost:(+t.quantity*+t.price)+(+t.fees||0)});}else {let remaining=+t.quantity,used=0;for(const c of chunks){if(remaining<=1e-9)break;if(c.q<=1e-9)continue;const take=Math.min(c.q,remaining);const unitCost=c.cost/c.q;used+=take*unitCost;c.cost-=take*unitCost;c.q-=take;remaining-=take;}realized+=(t.quantity*t.price-(+t.fees||0))-used;}}
const qty=chunks.reduce((a,x)=>a+x.q,0),cost=chunks.reduce((a,x)=>a+x.cost,0);const rec=cache[symbol];const quote=rec&&rec.price;const mismatch=!!(rec&&!rec.demo&&(!rec.currency||!currency||rec.currency.toUpperCase()!==currency.toUpperCase()));const value=qty>0&&!mismatch&&Number.isFinite(quote)?qty*quote:null;return {symbol,name,currency:currency||'USD',qty,cost,avg:qty?cost/qty:null,realized,price:!mismatch&&Number.isFinite(quote)?quote:null,value,unrealized:value===null?null:value-cost,pnlPct:value===null||cost===0?null:(value/cost-1)*100,rec,records,hasTrade,mismatch};}
