function sma(vals,n){if(vals.length<n)return null;return vals.slice(-n).reduce((a,b)=>a+b,0)/n;}
function pivots(candles){if(candles.length<50)return[];const out=[{i:0,p:candles[0].close}];let mode=0,extIdx=0,ext=candles[0].close,threshold=.064;for(let i=1;i<candles.length;i++){const p=candles[i].close;if(mode===0){if(p>ext*(1+threshold)){mode=1;ext=p;extIdx=i;}else if(p<ext*(1-threshold)){mode=-1;ext=p;extIdx=i;}}else if(mode===1){if(p>ext){ext=p;extIdx=i;}else if(p<ext*(1-threshold)){out.push({i:extIdx,p:ext});mode=-1;ext=p;extIdx=i;}}else {if(p<ext){ext=p;extIdx=i;}else if(p>ext*(1+threshold)){out.push({i:extIdx,p:ext});mode=1;ext=p;extIdx=i;}}}if(out.length===1||extIdx!==out[out.length-1].i)out.push({i:extIdx,p:ext});return out.filter((p,i)=>!i||p.i!==out[i-1].i);}
function validImpulse(p){if(p.length<6)return false;const a=p.slice(-6).map(x=>x.p);let up=a[1]>a[0];const seq=[1,-1,1,-1,1].map(x=>up?x:-x);for(let j=1;j<6;j++)if(Math.sign(a[j]-a[j-1])!==seq[j-1])return false;let d1=Math.abs(a[1]-a[0]),d3=Math.abs(a[3]-a[2]),d5=Math.abs(a[5]-a[4]);return d3>=Math.min(d1,d5)&& (up?a[2]>a[0]&&a[4]>a[1]:a[2]<a[0]&&a[4]<a[1]);}
function technical(rec){if(!rec||!Array.isArray(rec.candles)||rec.candles.length<55)return null;const bars=rec.candles,prices=bars.map(c=>c.close),p=prices.at(-1),avg20=sma(prices,20),avg50=sma(prices,50),mom=(p/prices.at(-21)-1)*100;const bullish=avg20>avg50*1.012&&mom>1,bearish=avg20<avg50*.988&&mom< -1,trend=bullish?'bull':bearish?'bear':'side';const region=bars.slice(-95),lo=Math.min(...region.map(c=>c.low)),hi=Math.max(...region.map(c=>c.high)),range=hi-lo;let support=lo, resistance=hi;
const primary=bullish?'bull':bearish?'bear':'side';const buy=[hi-.618*range,hi-.382*range], sell=[lo+.382*range,lo+.618*range];const bTarget=[hi+.272*range,hi+.618*range],dTarget=[Math.max(0,lo-.618*range),Math.max(0,lo-.272*range)];const invalidBull=lo-.06*range,invalidBear=hi+.06*range;
const pp=pivots(bars);const isImpulse=validImpulse(pp);let analysisConfidence=pp.length>=6?'Struktur-Indizien vorhanden':'Wenige bestätigte Swingpunkte';return {trend,primary,price:p,avg20,avg50,mom,lo,hi,range,buy,sell,bTarget,dTarget,invalidBull,invalidBear,support,resistance,pivots:pp,impulse:isImpulse,analysisConfidence,hasWaveCount:isImpulse};}
function scenarioWeight(rec){const t=technical(rec);if(!t)return null;const clamp=(n,lo,hi)=>Math.max(lo,Math.min(hi,n));const smaGap=(t.avg20/t.avg50-1)*100;const m=t.mom;const rangeLoc=t.range>0?(t.price-t.lo)/t.range:.5;const s1=clamp(smaGap*7,-17,17),s2=clamp(m*1.8,-19,19),s3=clamp((rangeLoc-.5)*16,-8,8),s4=t.impulse?(t.price>=t.avg20?4:-4):0;const raw=50+s1+s2+s3+s4;const bull=clamp(Math.round(raw),20,80),bear=100-bull;const recentSwing=t.pivots.length>0&&t.pivots.at(-1).i>=rec.candles.length-11;const conflicting=Math.sign(s1)!==Math.sign(s2)&&Math.abs(s1)>4&&Math.abs(s2)>4;const pivot=Math.abs(bull-50)<9||conflicting||(recentSwing&&Math.abs(bull-50)<16);const status=pivot?'Richtung offen · möglicher Wendebereich':bull>=62?'Bullische Tendenz':bull<=38?'Bärische Tendenz':bull>=50?'Leicht bullische Tendenz':'Leicht bärische Tendenz';return {bull,bear,status,pivot,conflicting,components:[{label:'SMA 20 / SMA 50',points:s1},{label:'Momentum (20 Tage)',points:s2},{label:'Lage im Kurskorridor',points:s3},{label:'Impuls-Kandidat',points:s4}],method:'Heuristische Szenario-Gewichtung; NICHT statistisch kalibrierte Wahrscheinlichkeit. Ohne Backtesting kein Trefferquotenversprechen.'};}
function decisionPanel(rec){const sw=scenarioWeight(rec),t=technical(rec),c=rec?.currency||'USD';if(!sw)return `<section class="outlook-hero empty-outlook"><div><span class="outlook-kicker">MARKTRICHTUNG</span><h2>Aktuell noch nicht bewertbar</h2><p>Für ${esc(selected)} fehlen historische Kursdaten. Erst nach erfolgreichem Datenabruf werden Prozent-Gewichtungen und Zielzonen berechnet.</p></div><button class="btn btn-primary" id="refresh-one">Kursdaten laden</button></section>`;return `<section class="outlook-hero ${sw.pivot?'outlook-pivot':sw.bull>sw.bear?'outlook-up':'outlook-down'}"><div class="outlook-intro"><span class="outlook-kicker">ELLIOTT-WAVE · TRENDKOMPASS <span class="card-status ${rec?.demo?'demo':''}">${rec?.demo?'DEMO':esc(rec?.provider||'DATEN')}</span></span><h2>${sw.pivot?'↔':sw.bull>=sw.bear?'↗':'↘'} ${esc(sw.status)}</h2><p>${sw.pivot?'Die Signale widersprechen sich oder sind ähnlich stark. Entscheidend sind jetzt die nächsten Bestätigungsmarken.':sw.bull>sw.bear?'Die aktuellen Indikatoren gewichten eine Aufwärtsfortsetzung stärker als die bärische Alternative.':'Die aktuellen Indikatoren gewichten eine Abwärtsfortsetzung stärker als die bullische Alternative.'}</p><div class="decision-marks"><span>↗ Über ${money(t.resistance,c)}: bullische Bestätigung</span><span>↘ Unter ${money(t.support,c)}: bärische Bestätigung</span></div></div><div class="outlook-numbers"><div class="outlook-values"><div><small>BULLISCH</small><strong>${sw.bull}<span>%</span></strong></div><div class="outlook-bear"><small>BÄRISCH</small><strong>${sw.bear}<span>%</span></strong></div></div><div class="outlook-track"><span style="width:${sw.bull}%"></span></div><div class="outlook-caption">Indikative Gewichtung · <b>keine gemessene Wahrscheinlichkeit</b></div></div></section>`;}
function fundamentals(rec){const f=rec?.fundamentals;if(!f||isAlternativeAsset(rec?.symbol))return null;const valid=(key)=>Number.isFinite(f[key]);const pe=valid('pe')?f.pe:null,leverage=valid('debtEquity')?f.debtEquity:null,liquidity=valid('currentRatio')?f.currentRatio:null,margin=valid('profitMargin')?f.profitMargin:null,fcf=valid('freeCashFlow')?f.freeCashFlow:null;const items=[pe,leverage,liquidity,margin,fcf].filter(v=>v!==null);if(!items.length)return null;
let score=0,count=0;const add=(val)=>{if(val!=null){score+=val;count++;}};add(pe===null?null:pe<=0?15:pe<12?88:pe<25?70:pe<40?48:25);add(leverage===null?null:leverage<0?12:leverage<.4?90:leverage<1?74:leverage<2?49:21);add(liquidity===null?null:liquidity>1.7?87:liquidity>1.1?66:liquidity>.8?40:12);add(margin===null?null:margin>.2?85:margin>.08?70:margin>0?53:13);add(fcf===null?null:fcf>0?77:fcf===0?45:20);return {pe,leverage,liquidity,margin,fcf,score:Math.round(score/count),coverage:count,reportDate:f.reportDate||'—',cash:valid('cashAndEquivalents')?f.cashAndEquivalents:null,totalDebt:valid('totalDebt')?f.totalDebt:null,interestCoverage:valid('interestCoverage')?f.interestCoverage:null,operatingCashFlow:valid('operatingCashFlow')?f.operatingCashFlow:null,reportedCurrency:f.reportedCurrency||null};}
function stress(rec){const f=fundamentals(rec);if(!f)return null;let risk=0,unknown=0;let factors=[];if(f.leverage==null)unknown++;else if(f.leverage<0){risk+=2;factors.push('Negatives Eigenkapital');}else if(f.leverage>2){risk+=2;factors.push('Hohe Verschuldung im Verhältnis zum Eigenkapital');}else if(f.leverage>1){risk++;factors.push('Schuldenbelastung beachten');}if(f.liquidity==null)unknown++;else if(f.liquidity<.8){risk+=2;factors.push('Schwache kurzfristige Liquidität');}else if(f.liquidity<1.2){risk++;factors.push('Geringer Liquiditätspuffer');}if(f.fcf==null)unknown++;else if(f.fcf<0){risk+=2;factors.push('Negativer freier Cashflow');}if(f.margin==null)unknown++;else if(f.margin<0){risk+=1;factors.push('Negatives Ergebnis');}if(f.interestCoverage!==null&&f.interestCoverage<1.5){risk+=2;factors.push('Schwache Zinsdeckung');}if(f.operatingCashFlow!==null&&f.operatingCashFlow<0){risk+=1;factors.push('Negativer operativer Cashflow');}if(f.cash!==null&&f.totalDebt!==null&&f.totalDebt>f.cash*3){risk+=1;factors.push('Schulden deutlich über Kassenbestand');}const reportAge=f.reportDate&&/^\d{4}-\d{2}-\d{2}$/.test(f.reportDate)?(Date.now()-Date.parse(f.reportDate))/86400000:null;if(reportAge!==null&&reportAge>250){factors.push('Unternehmensbericht älter als 250 Tage');unknown+=1;}return {risk,unknown,factors,label:unknown>=3?'Nicht belastbar':risk>=4?'Erhöhte Stressindikatoren':risk>=2?'Beobachten':'Keine starken Warnsignale',notProb:true};}
function isAlternativeAsset(s){return ASSET_GROUPS.metals.some(x=>x.symbol===s)||ASSET_GROUPS.crypto.some(x=>x.symbol===s);}
function ranking(rec){const t=technical(rec),f=fundamentals(rec);if(!t||!f)return null;const tech=t.trend==='bull'?82:t.trend==='side'?52:23,score=Math.round(.65*f.score+.35*tech);return {score,tech,fund:f.score};}
