function pfMetrics(){const positions=symbolsHeld().map(position);const byCurr={};for(const p of positions){const c=p.currency;if(!byCurr[c])byCurr[c]={cost:0,value:0,pnl:0,missing:0};const a=byCurr[c];if(p.value==null){a.missing++;}else{a.cost+=p.cost;a.value+=p.value;a.pnl+=p.unrealized;}}return {positions,byCurr};}
function pftotalsHtml(p){const currencies=Object.entries(p.byCurr).filter(([k,v])=>v.value!==0);if(!currencies.length)return `<span class="muted">Noch keine bewertbaren Positionen</span>`;return currencies.map(([c,x])=>`<div><strong class="${classPN(x.pnl)}">${money(x.value,c)}</strong><small class="muted"> · ${pct(x.cost?(x.pnl/x.cost*100):null)} · ${x.missing?x.missing+' ohne Kurs':''}</small></div>`).join('');}
function overviewPage(){const pf=pfMetrics(),selectedRec=cache[selected]||null,valid=pf.positions.filter(p=>p.value!=null),stresses=pf.positions.map(p=>stress(p.rec)).filter(Boolean).filter(s=>s.risk>=2);return pageHead('DEINE FINANZEN IM BLICK','Gute Entscheidungen beginnen mit Überblick.','Dein Depot, klar gerechnete Renditen und chartbasierte Szenarien – alles an einem Ort.',`<button class="btn" data-page="briefing">☼ Morgenbriefing</button><button class="btn btn-primary" id="add-transaction">+ Kauf erfassen</button>`)+banner()+`<div class="metric-grid">${metric('Depotbewertung',pftotalsHtml(pf),`<strong>${valid.length}</strong> von ${pf.positions.length} Positionen bewertet`)}${metric('Depotpositionen',String(pf.positions.length),`${state.transactions.length} einzelne Transaktionen`)}${metric('Watchlist',String(state.watchlist.length),`Individuelle Beobachtungsliste`)}${metric('Risikohinweise',stresses.length?String(stresses.length):'—',stresses.length?'Positionen mit Stressindikatoren':'Ohne Fundamentaldaten keine Risikofreigabe','warn')}</div>
<div class="layout"><div class="stack">${chartPanel(selectedRec,false)}${tablePositions(pf.positions,true)}</div><div class="stack">${scenarioPanel(selectedRec)}${watchMini()}${activityPanel()}</div></div>`;}
function chartPanel(rec,big){const ana=technical(rec),p=rec?.price,cc=rec?.currency||'USD';return `<section class="panel"><div class="chart-titlebar"><div><div class="ticker-line"><h2>${esc(rec?.name||selected)}</h2><span class="symbol-badge">${esc(selected)}</span>${rec?.demo?'<span class="card-status demo">SIMULIERT</span>':''}</div><div class="instrument-name">${rec?esc(rec.quoteKind||'Historische Kursdaten · Zeitpunkt prüfen'):'Keine Marktdaten geladen'} · ${esc(rec?.asof||'—')}</div></div><div><div class="chart-price">${money(p,cc)}</div><div style="text-align:right;margin-top:4px">${ana?trendPill(ana.trend):'<span class="pill neutral">Nicht bewertet</span>'}</div></div></div><div class="chart-legend"><div class="legend-item"><span class="swatch"></span> Kurs / Wellen</div><div class="legend-item"><span class="swatch gold"></span> Bullische Zielzone</div><div class="legend-item"><span class="swatch coral"></span> Bärische Zielzone</div><div class="legend-item"><span class="swatch blue"></span> Einstiegsbereich</div></div><div class="chart-outer ${big?'big':''}"><div class="chart-root" id="chart-main" style="width:100%;height:100%"></div></div><div class="chart-time"><div class="range-control">${[['1M','1 Monat'],['3M','3 Monate'],['1J','1 Jahr'],['3J','bis 3 Jahre']].map(([v,title])=>`<button data-range="${v}" title="${title}" class="${timeRange===v?'active':''}">${v}</button>`).join('')}</div><span class="footnote">${dataSource(rec)} · Heuristische Elliott-Interpretation · ${rec?.candles?.length||0} verfügbare Tageskerzen</span></div></section>`;}
function scenarioPanel(rec){const a=technical(rec),c=rec?.currency||'USD';if(!a)return `<section class="panel panel-inner"><div class="panel-head"><div class="panel-title">Szenario-Monitor</div></div><div class="empty-state"><h3>Keine belastbaren Szenarien</h3><p>Mindestens 55 tägliche Kurskerzen werden für eine Trendheuristik benötigt. Starte den lokalen Server und verbinde eine Marktdatenquelle.</p><button class="btn btn-small" data-page="settings">API konfigurieren</button></div></section>`;const sw=scenarioWeight(rec);return `<section class="panel panel-inner"><div class="panel-head"><div><div class="panel-title">Szenario-Monitor</div><div class="panel-sub">Gewichtete Alternativen · Fibonacci</div></div><span class="card-status">${a.impulse?'Impuls-Kandidat':'Wellenzählung offen'}</span></div><div class="scenario-grid"><div class="scenario"><div class="top">↗ BULLISCH ${sw.bull}% <span>MÖGLICHE ZONE</span></div><strong>${money(a.bTarget[0],c)}</strong><span>bis ${money(a.bTarget[1],c)}</span></div><div class="scenario bear"><div class="top">↘ BÄRISCH ${sw.bear}% <span>MÖGLICHE ZONE</span></div><strong>${money(a.dTarget[0],c)}</strong><span>bis ${money(a.dTarget[1],c)}</span></div></div><div class="section-split"></div><div class="key-list"><div class="keyrow"><span>Trendheuristik</span>${trendPill(a.trend)}</div><div class="keyrow"><span>Potenzielle Kauf-/Rücklaufzone</span><strong>${rangeText(a.buy,c)}</strong></div><div class="keyrow"><span>Bullisch ungültig ab*</span><strong class="neg">${money(a.invalidBull,c)}</strong></div><div class="keyrow"><span>Bärisch ungültig ab*</span><strong class="pos">${money(a.invalidBear,c)}</strong></div></div><div class="hr"></div><button class="btn btn-small btn-ghost" data-page="analyse">Zur vollständigen Chartanalyse →</button><p class="footnote">*Automatisch abgeleitete Heuristikmarken; keine HKCM-Kursziele oder garantierte Elliott-Wellenzählung. Die Prozentwerte sind gewichtete Regeln, keine belegten Eintrittswahrscheinlichkeiten.</p></section>`;}
function tablePositions(positions,short=false){const data=short?positions.slice(0,6):positions;return `<section class="panel"><div class="panel-inner" style="padding-bottom:0"><div class="panel-head"><div><div class="panel-title">${short?'Deine Depotpositionen':'Positionen & Einstandskurse'}</div><div class="panel-sub">Anschaffungswert aus einzelnen Transaktionen · FIFO bei Verkäufen</div></div><button class="panel-action" data-page="portfolio">Alle Positionen →</button></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Wertpapier</th><th>Bestand</th><th>Ø Kaufpreis</th><th>Aktueller Kurs</th><th>Unrealisiert</th><th>Aktion</th></tr></thead><tbody>${data.length?data.map(p=>`<tr><td><div class="mini-symbol">${esc(p.symbol)} ${p.rec?.demo?'<span class="tag">Demo</span>':''}</div><div class="sub-row">${esc(p.name)}${p.records.some(t=>t.isin)?' · ISIN '+esc(p.records.find(t=>t.isin).isin):''}</div></td><td>${fmt(p.qty,4)}</td><td>${money(p.avg,p.currency)}</td><td>${p.mismatch?'<span class="warn">Währung abweichend</span>':money(p.price,p.currency)}</td><td class="${classPN(p.unrealized)}">${money(p.unrealized,p.currency)}<div class="sub-row ${classPN(p.pnlPct)}">${pct(p.pnlPct)}</div></td><td><button class="linkish" data-detail="${esc(p.symbol)}">Öffnen ↗</button></td></tr>`).join(''):'<tr><td colspan="6" class="empty-state">Noch keine Positionen. Über „+ Kauf / Verkauf“ kannst du deine ersten Käufe erfassen.</td></tr>'}</tbody></table></div></section>`;}
function watchMini(){return `<section class="panel panel-inner"><div class="panel-head"><div><div class="panel-title">Im Fokus</div><div class="panel-sub">Deine Watchlist · unabhängig vom Depot</div></div><button class="panel-action" data-page="watchlist">Alle →</button></div><div class="list-cards">${state.watchlist.slice(0,4).map(w=>{let rec=cache[w.symbol],a=technical(rec);return `<div class="watch-row"><div class="watch-logo">${esc(w.symbol.slice(0,2))}</div><div class="watch-info"><b>${esc(w.symbol)}</b><small>${esc(w.name||STOCK_NAMES[w.symbol]||w.symbol)}</small></div><div class="watch-price">${money(rec?.price,rec?.currency)}<small>${a?trendLabel(a.trend):'Kurs nicht geladen'}</small></div><button class="linkish" data-detail="${esc(w.symbol)}">↗</button></div>`;}).join('')||'<div class="muted">Noch keine Watchlist-Einträge.</div>'}</div></section>`;}
function activityPanel(){return `<section class="panel panel-inner"><div class="panel-head"><div class="panel-title">Hinweise & letzte Ereignisse</div></div>${state.notifications.length?state.notifications.slice(0,4).map(e=>`<div class="data-row"><span>${esc(e.when)} · ${esc(e.symbol)}</span><strong>${esc(e.text)}</strong></div>`).join(''):'<p class="explainer">Noch keine Alarme ausgelöst. Lege im Alarm-Center Kurszonen fest, um sie bei Kursaktualisierungen zu prüfen.</p>'}<div class="hr"></div><button class="btn btn-small btn-ghost" data-page="alerts">Alarm-Center öffnen →</button></section>`;}
function portfolioPage(){let p=pfMetrics(),demoOnly=p.positions.length===1&&p.positions[0].symbol==='DEMO';const currencyCards=Object.entries(p.byCurr).map(([c,v])=>`<div class="line-block"><div class="muted" style="font-size:11px">DEPOT · ${c}</div><div class="stat-big">${v.value?money(v.value,c):'Kein Kurs'}</div><div class="${classPN(v.pnl)}" style="font-size:12px">${v.value?pct(v.pnl/v.cost*100):'Rendite erst mit realen Kursen'}</div><div class="sub-row">${v.missing} Position(en) ohne aktuellen Kurs</div></div>`).join('');return pageHead('DEINE POSITIONEN','Mein Depot','Jeden Kauf und Verkauf separat erfassen. Der offene Bestand wird automatisch nach FIFO ermittelt.',`<button class="btn" id="export-json">Depot sichern</button><button class="btn btn-primary" id="add-transaction">+ Kauf eintragen</button>`)+banner()+`${demoOnly?'<div class="status-note"><strong>Nur Demo-Bestand vorhanden.</strong> Du kannst das Musterdepot entfernen. Deine echten Wertpapierkäufe werden nicht vorgegeben.</div>':''}<div class="grid-3" style="margin-bottom:19px">${currencyCards||'<div class="line-block"><div class="muted">Noch keine echten Positionen.</div></div>'}<div class="line-block"><div class="muted" style="font-size:11px">ERFASSTE TRANSAKTIONEN</div><div class="stat-big">${state.transactions.length}</div><p class="muted">Käufe und Verkäufe · lokal gespeichert</p></div><div class="line-block"><div class="muted" style="font-size:11px">AKTIVE POSITIONEN</div><div class="stat-big">${p.positions.length}</div><p class="muted">Einschließlich Demo, falls vorhanden</p></div></div>${tablePositions(p.positions)}<section class="panel" style="margin-top:18px"><div class="panel-inner"><div class="panel-head"><div><div class="panel-title">Transaktionsjournal</div><div class="panel-sub">Original-Einträge mit Kaufdatum, Stückzahl, Kurs, Gebühren</div></div><div class="btn-row"><button class="btn btn-small btn-ghost" id="export-json">JSON-Backup</button><button class="btn btn-small btn-ghost" id="restore-json">Backup einlesen</button>${state.transactions.some(t=>t.demo)?'<button class="btn btn-small btn-danger" id="remove-demo">Demodepot entfernen</button>':''}</div></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Datum</th><th>Aktie</th><th>Vorgang</th><th>Stück</th><th>Kurs</th><th>Gebühren</th><th></th></tr></thead><tbody>${state.transactions.length?state.transactions.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(t=>`<tr><td>${dateDe(t.date)}</td><td><b>${esc(t.symbol)}</b>${t.demo?' <span class="tag">Demo</span>':''}</td><td>${t.type==='buy'?'<span class="pill">KAUF</span>':'<span class="pill bear">VERKAUF</span>'}</td><td>${fmt(t.quantity,4)}</td><td>${money(t.price,t.currency)}</td><td>${money(t.fees||0,t.currency)}</td><td><button class="linkish" data-remove-tx="${esc(t.id)}">Entfernen</button></td></tr>`).join(''):'<tr><td colspan="7">Noch keine Transaktionen erfasst.</td></tr>'}</tbody></table></div></section><p class="side-note">Hinweis: Aktiensplits, Bezugsrechte, Spin-offs, Steuern und Wechselkurse werden noch nicht automatisch gebucht. Gerade bei Canopy Growth solltest du historische Reverse-Splits berücksichtigen, wenn ältere Käufe eingetragen werden.</p>`;}
function watchlistPage(){return pageHead('INTERESSEN / BEOBACHTUNG','Deine Watchlist','Aktien verfolgen, ohne sie zu besitzen. Mögliche Einstiegs- und Verkaufszonen entstehen erst aus geladenen historischen Kursreihen.',`<button class="btn btn-ghost" id="refresh-watch">Watchlist aktualisieren</button><button class="btn btn-primary" id="add-watch">+ Aktie hinzufügen</button>`)+banner()+`<div class="panel"><div class="panel-inner"><div class="panel-head"><div><div class="panel-title">Beobachtete Aktien</div><div class="panel-sub">Bullische und bärische Alternativen · pro Symbol</div></div><span class="card-status">${state.watchlist.length} Titel</span></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Symbol / Name</th><th>Letzter Kurs</th><th>Marktbild</th><th>Potenzielle Kaufzone</th><th>Potenzielle Zielzone</th><th></th></tr></thead><tbody>${state.watchlist.length?state.watchlist.map(w=>{const rec=cache[w.symbol],a=technical(rec),c=rec?.currency||'USD';return `<tr><td><b class="mini-symbol">${esc(w.symbol)}</b><div class="sub-row">${esc(w.name||STOCK_NAMES[w.symbol]||w.symbol)}</div></td><td>${money(rec?.price,c)}<div class="sub-row">${esc(rec?.quoteKind||'Keine Daten')}</div></td><td>${a?trendPill(a.trend):'<span class="pill neutral">Ausstehend</span>'}</td><td>${a?rangeText(a.buy,c):'—'}</td><td>${a?rangeText(a.bTarget,c):'—'}</td><td><button class="linkish" data-detail="${esc(w.symbol)}">Analyse ↗</button> <button class="linkish neg" data-remove-watch="${esc(w.symbol)}" title="Aus Watchlist entfernen">✕</button></td></tr>`}).join(''):'<tr><td colspan="6" class="empty-state">Noch keine Watchlist-Titel. Füge beispielsweise CGC oder NVDA hinzu.</td></tr>'}</tbody></table></div></div><div class="help-box" style="margin-top:18px"><h3>Was die Watchlist automatisch macht</h3><p>Bei Verbindung mit einem Datenanbieter kann jeder Titel auf seinen Trend, 20-/50-Tage-Durchschnitt, lokale Swings sowie Fibonacci-Zonen geprüft werden. Das sind regelbasierte Näherungen, keine verifizierten Kauf- oder Verkaufssignale. Eine Bewertung ohne valide historische Daten wird nicht erzeugt.</p></div>`;}
function marketCard(inst){const r=cache[inst.symbol],t=technical(r),sw=scenarioWeight(r),nonstandard=inst.symbol==='BRONZE';return `<article class="instrument-card"><div class="instrument-card-top"><span class="instrument-symbol">${esc(inst.symbol)}</span><span class="tag">${esc(inst.kind)}</span></div><h3>${esc(inst.name)}</h3><p>${esc(inst.unit)} · ${nonstandard?'Kein einheitlicher Börsenreferenzpreis; individuelle Marktpreise nötig':r?esc(r.asof||'Datenstand unbekannt'):'Noch kein Kurs geladen'}</p><div class="instrument-quote">${nonstandard?'—':money(r?.price,r?.currency||'USD')}</div>${sw?`<div class="instrument-weights"><span>↗ ${sw.bull}%</span><div><i style="width:${sw.bull}%"></i></div><span>↘ ${sw.bear}%</span></div><small class="instrument-state">${esc(sw.status)} · Szenario-Gewichtung</small>`:`<small class="instrument-state">${nonstandard?'Nur als eigener manueller Eintrag · keine automatische EW-Prognose':'Bewertung erst nach gültigem API-Abruf'}</small>`}<div class="instrument-actions">${nonstandard?'<button class="btn btn-small" data-watch="BRONZE">+ Merken</button><button class="btn btn-small" data-custom-trade="BRONZE">Manuell erfassen</button>':`<button class="btn btn-primary btn-small" data-detail="${inst.symbol}">Chart & Analyse</button><button class="btn btn-small" data-market-load="${inst.symbol}">↻ Kurs laden</button><button class="btn btn-small" data-watch="${inst.symbol}">+ Merken</button>`}</div></article>`;}
function assetCategoryPage(which){const metal=which==='metals';const group=ASSET_GROUPS[which];return pageHead(metal?'ROHSTOFFE & EDELMETALLE':'DIGITALE VERMÖGENSWERTE',metal?'Edelmetalle im Überblick':'Bitcoin & Kryptowährungen',metal?'Gold, Silber, Platin und Palladium mit Elliott-Szenarien; Bronze als individueller Materialwert.':'Bitcoin, Ethereum und weitere Coins mit Trendkompass, Chart und Zielzonen.',`<button class="btn btn-primary" data-page="watchlist">Zur Watchlist →</button>`)+banner()+`<div class="asset-intro"><div><strong>${metal?'Ein eigenes Marktsegment für Sachwerte.':'Ein eigener Bereich für digitale Märkte.'}</strong><p>${metal?'Werte sind in USD je Feinunze vorgesehen. Bronze besitzt keinen einheitlichen transparenten Spotmarkt; deshalb zeigen wir dort keine erfundene Notierung.':'Kryptomärkte handeln rund um die Uhr. Die EW-Gewichtung nutzt historische Kurse, nicht Unternehmens-KGV oder Insolvenzquoten.'}</p></div><span>◈ SBro MARKTBLICK</span></div><div class="instrument-grid">${group.map(marketCard).join('')}</div><p class="side-note">Quellen: Kryptowährungen werden über die öffentliche Kraken-API geladen (ohne Schlüssel, lokaler Server erforderlich). Gold, Silber und Aktien benötigen Twelve Data und ggf. einen geeigneten Tarif. Nicht unterstützte Instrumente bleiben ohne Kurs. Die Prozentwerte sind heuristisch, keine kalibrierten Prognosewahrscheinlichkeiten.</p>`;}
function metalsPage(){return assetCategoryPage('metals');}
function cryptoPage(){return assetCategoryPage('crypto');}
function stockDropdown(){const opts=[...new Set([selected,...allTracked(),...Object.values(SECTORS).flat(),...ASSET_GROUPS.metals.map(x=>x.symbol),...ASSET_GROUPS.crypto.map(x=>x.symbol)])];return `<select id="analyse-stock" class="search-field" style="min-width:195px">${opts.map(s=>`<option value="${esc(s)}" ${selected===s?'selected':''}>${esc(s)} · ${esc(STOCK_NAMES[s]||s)}</option>`).join('')}</select>`;}
function analysePage(){const rec=cache[selected],a=technical(rec),f=fundamentals(rec),s=stress(rec),rank=ranking(rec),c=rec?.currency||'USD';return pageHead('WELLENSTRUKTUR / SZENARIEN','Elliott-Wave-Analyse','Chartzonen nach Fibonacci, Marktswings und Trenddaten. Konkurrierende Szenarien bleiben sichtbar.',`${stockDropdown()}<button class="btn" id="refresh-one">↻ Kursreihe laden</button><button class="btn btn-primary" id="add-alert-for">+ Alarm anlegen</button>`)+banner()+`${decisionPanel(rec)}<div class="layout narrow-right"><div class="stack">${chartPanel(rec,true)}${analysisNarrative(rec,a)}${aiPanel(rec,a,f)}</div><div class="stack">${scenarioPanel(rec)}${indicatorsPanel(rec,a,f,s,rank)}${tradesPanel(selected)}<div class="help-box"><h3>Wellenzählung ist kein Naturgesetz</h3><p>Swings werden mit einer festen Umkehrschwelle erkannt. Nur wenn die getesteten Impulsbedingungen erfüllt sind, markiert SBro einen möglichen 5er-Impuls; ansonsten bleibt die Wellenzählung offen. Die späteren A-B-C-Wellen bedürfen zusätzlicher Bestätigung. Szenarien können sich bei neuen Kursdaten ändern.</p></div></div></div>`;}
function analysisNarrative(rec,a){if(!a)return `<section class="panel panel-inner"><h2 class="section-title">Analyse noch nicht verfügbar</h2><p class="explainer">Für ${esc(selected)} liegen noch nicht genügend valide Kurstage vor. Der Kurschart, mögliche Zielzonen und die Fundamentaldaten bleiben bis zur erfolgreichen API-Abfrage leer.</p><button class="btn" data-page="settings">Datenquelle einrichten</button></section>`;const c=rec.currency;return `<section class="panel panel-inner"><div class="panel-head"><div><div class="panel-title">Wellen- & Marktstrukturbericht</div><div class="panel-sub">Nachvollziehbare Regeln statt unprüfbarer Prognose</div></div>${trendPill(a.trend)}</div><p class="explainer"><strong>Aktueller Trend:</strong> ${a.trend==='bull'?'Kurzfristiger Durchschnitt über dem mittelfristigen, positives 20-Tage-Momentum.':a.trend==='bear'?'Kurzfristiger Durchschnitt unter dem mittelfristigen, negatives 20-Tage-Momentum.':'Gemischte Signale der kurzfristigen und mittelfristigen Trendindikatoren.'} ${a.impulse?'Die letzten sechs Wendepunkte erfüllen eine vereinfachte 5-Wellen-Impulsprüfung. Das ist eine Kandidatenzählung und keine eindeutige Elliott-Zuordnung.':'Eine eindeutig plausible Fünfwellen-Struktur lässt sich mit der verwendeten Schwellenheuristik derzeit nicht bestätigen.'}</p><div class="details-grid"><div><small>SMA 20</small><b>${money(a.avg20,c)}</b></div><div><small>SMA 50</small><b>${money(a.avg50,c)}</b></div><div><small>20 Tage Momentum</small><b class="${classPN(a.mom)}">${pct(a.mom)}</b></div><div><small>Bestätigte Swings</small><b>${a.pivots.length}</b></div></div><div class="hr"></div><p class="explainer"><strong>Bullische Variante:</strong> Eine Fortsetzung über ${money(a.resistance,c)} eröffnet rechnerisch den Fibonacci-Projektionsbereich ${rangeText(a.bTarget,c)}. <strong>Bärische Variante:</strong> Unterhalb ${money(a.support,c)} liegt der rechnerische Korrekturbereich ${rangeText(a.dTarget,c)}. Das sind Szenariomarken, keine zeitlich oder statistisch kalibrierten Prognosen.</p><div class="status-note">Die Zonen basieren auf dem jüngsten 95-Tage-Korridor und Fibonacci-Verhältnissen; nicht auf HKCM-Originalanalysen. Symbol, Börse, Handelswährung und Kursstand prüfen.</div></section>`;}
function indicatorsPanel(rec,a,f,s,rank){const formatF=(v,unit='')=>v===null||v===undefined?'Nicht verfügbar':fmt(v,2)+unit;return `<section class="panel panel-inner"><div class="panel-head"><div><div class="panel-title">${isAlternativeAsset(rec?.symbol)?'Instrumentendaten & Risiken':'Fundamentale Qualität'}</div><div class="panel-sub">Nur verfügbare, zuordenbare Werte</div></div>${rank?`<span class="pill">${rank.score}/100</span>`:'<span class="pill neutral">Unvollständig</span>'}</div><div class="key-list"><div class="keyrow"><span>KGV / P-E</span><strong>${formatF(f?.pe)}</strong></div><div class="keyrow"><span>Debt / Equity</span><strong>${formatF(f?.leverage)}</strong></div><div class="keyrow"><span>Current Ratio</span><strong>${formatF(f?.liquidity)}</strong></div><div class="keyrow"><span>Gewinnmarge</span><strong>${f?.margin!=null?fmt(f.margin*100,2)+' %':'Nicht verfügbar'}</strong></div><div class="keyrow"><span>Zinsdeckung</span><strong>${formatF(f?.interestCoverage)}</strong></div><div class="keyrow"><span>Operativer Cashflow</span><strong>${f?.operatingCashFlow==null?'Nicht verfügbar':new Intl.NumberFormat('de-DE',{notation:'compact',maximumFractionDigits:2}).format(f.operatingCashFlow)+' '+esc(f.reportedCurrency||'Berichtswährung nicht angegeben')}</strong></div><div class="keyrow"><span>Freier Cashflow</span><strong>${f?.fcf==null?'Nicht verfügbar':new Intl.NumberFormat('de-DE',{notation:'compact',maximumFractionDigits:2}).format(f.fcf)+' '+esc(f.reportedCurrency||'Berichtswährung unbekannt')}</strong></div></div><div class="hr"></div><div class="mini-head"><h3>Finanzstress-Signale</h3><span class="${s&&s.risk>=3?'neg':'muted'}" style="font-size:11px">${esc(s?.label||'Daten fehlen')}</span></div><div class="risk-band">${Array.from({length:4},(_,i)=>`<span class="${s&&i<Math.ceil(s.risk/2)?'active':''}"></span>`).join('')}</div><p class="explainer">${s?.factors.length?esc(s.factors.join(' · ')):'Keine automatisierte Risikobewertung aus unvollständigen Daten ableitbar.'} ${s?.unknown?'Fehlende Indikatoren: '+s.unknown+'.':''} Kein Insolvenz-Wahrscheinlichkeitsmodell.</p><div class="source-line">Quelle: ${esc(rec?.fundamentals?.source|| (rec?.demo?'Demo':'nicht verbunden'))} · Stand: ${esc(f?.reportDate||'—')} · ${f?.coverage||0}/5 Basiskennzahlen</div></section>`;}
function tradesPanel(symbol){const p=position(symbol),data=p.records;return `<section class="panel panel-inner"><div class="panel-head"><div class="panel-title">Dein Einstand · ${esc(symbol)}</div><button class="panel-action" id="add-tx-current">+ Buchung</button></div>${data.length?`<div class="key-list"><div class="keyrow"><span>Verbleibende Stückzahl</span><strong>${fmt(p.qty,4)}</strong></div><div class="keyrow"><span>Ø Einstand (inkl. Gebühren)</span><strong>${money(p.avg,p.currency)}</strong></div><div class="keyrow"><span>Unrealisierter Gewinn / Verlust</span><strong class="${classPN(p.unrealized)}">${money(p.unrealized,p.currency)}</strong></div><div class="keyrow"><span>Unrealisierte Rendite</span><strong class="${classPN(p.pnlPct)}">${pct(p.pnlPct)}</strong></div><div class="keyrow"><span>Realisierter Gewinn / Verlust (FIFO)</span><strong class="${classPN(p.realized)}">${money(p.realized,p.currency)}</strong></div></div><div class="hr"></div><div class="muted" style="font-size:11px">${data.length} Einzeltransaktion(en)</div>`:'<div class="empty-state"><h3>Keine Position hinterlegt</h3><p>Du kannst mehrere Käufe für diese Aktie zu unterschiedlichen Kursen und Daten erfassen.</p><button class="btn btn-small" id="add-tx-current-2">+ Ersten Kauf erfassen</button></div>'}</section>`;}
function allEvents(symbol){const from=today();const remote=(marketEvents[symbol]?.events||[]).filter(x=>x.date>=from);const own=state.manualEvents.filter(x=>x.symbol===symbol&&x.date>=from).map(x=>({...x,verified:false,source:'Manuell · ungeprüft'+(x.source?' · '+x.source:'')}));return [...remote,...own].sort((a,b)=>a.date.localeCompare(b.date)).slice(0,30);}
function eventPanel(symbol){const alternative=isAlternativeAsset(symbol),events=allEvents(symbol);if(alternative)return '<section class="panel panel-inner"><h3>Unternehmensereignisse</h3><p class="explainer">Für Kryptowährungen und Edelmetalle gibt es keine Hauptversammlung oder Unternehmensinsolvenzkennzahlen.</p></section>';return `<section class="panel panel-inner"><div class="panel-head"><div><div class="panel-title">Unternehmensereignisse</div><div class="panel-sub">Veröffentlichte Ergebnistermine; Hauptversammlungen nur mit belegter Quelle oder manuell</div></div><button class="btn btn-small" id="load-events" ${!server.fmp?'disabled':''}>Termine aktualisieren</button></div>${events.length?events.map(e=>`<div class="data-row"><span><b>${esc(dateDe(e.date))}</b> · ${esc(e.label)}<small> · ${esc(e.verified?'Anbieterangabe':'Manuell, nicht geprüft')}</small></span><small>${esc(e.source||'')}</small></div>`).join(''):'<p class="explainer">Keine verifizierten kommenden Ereignisse geladen. Auch ohne Treffer können Termine existieren.</p>'}${eventErrors[symbol]?`<p class="side-note">Kalenderabfrage: ${esc(eventErrors[symbol])}</p>`:''}<form id="form-event" class="settings-report-form"><input name="symbol" type="hidden" value="${esc(symbol)}"><div class="form-grid"><div class="field"><label>Eigenen Termin eintragen</label><input type="date" name="date" min="${today()}" required></div><div class="field"><label>Terminart</label><select name="type"><option value="agm">Hauptversammlung (HV/AGM)</option><option value="earnings">Ergebnispräsentation</option><option value="other">Sonstiges</option></select></div><div class="field"><label>Quelle / Beschreibung</label><input name="source" maxlength="180" placeholder="z. B. Investor-Relations-Link"></div></div><button class="btn btn-small btn-primary" type="submit">Termin speichern (ungeprüft)</button></form><p class="side-note">Anbietertermine sind vorläufig und können verschoben werden. Eine manuell eingetragene Hauptversammlung gilt ausdrücklich nicht als extern verifiziert.</p></section>`;}
function aiPage(){const rec=cache[selected],tech=technical(rec),f=fundamentals(rec),risk=stress(rec),events=allEvents(selected);return pageHead('TRANSPARENTE AUSWERTUNG','KI-Analyse & Unternehmensrisiken','Marktdaten, Trend- und Elliott-Szenarien, Unternehmenstermine und Insolvenz-Frühwarnsignale – getrennt nach Datenquelle.',`${stockDropdown()}<button class="btn" id="refresh-company">↻ Kennzahlen & Termine aktualisieren</button>`)+banner()+`${decisionPanel(rec)}<div class="layout narrow-right"><div class="stack">${aiPanel(rec,tech,f)}${portfolioAiPanel()}${eventPanel(selected)}${analysisNarrative(rec,tech)}</div><div class="stack">${indicatorsPanel(rec,tech,f,risk,ranking(rec))}<section class="panel panel-inner"><h3>Datennachweis</h3><div class="key-list"><div class="keyrow"><span>Kursquelle</span><strong>${esc(rec?.provider||'Nicht vorhanden')}</strong></div><div class="keyrow"><span>Kursstand</span><strong>${esc(rec?.asof||'—')}</strong></div><div class="keyrow"><span>Fundamentaldaten</span><strong>${esc(f?.reportDate||'Nicht vorhanden')}</strong></div><div class="keyrow"><span>Erfasste Termine</span><strong>${events.length}</strong></div><div class="keyrow"><span>Insolvenz-Einschätzung</span><strong>${risk?esc(risk.label):'Nicht möglich'}</strong></div></div><p class="side-note">Die KI recherchiert nicht eigenständig. Sie interpretiert ausschließlich die vom Server gelieferten und von dir manuell hinterlegten Daten. Finanzstress ist keine belastbare Insolvenz-Eintrittswahrscheinlichkeit.</p></section></div></div>`;}
async function refreshCompanyAnalysis(){if(isAlternativeAsset(selected)||selected==='DEMO'){toast('Fundamentaldaten und HV gelten nur für Aktien.',true);return;}const symbol=selected;if(!server.connected){toast('Cloudflare-Server nicht verbunden.',true);return;}toast(symbol+': Kurs und Unternehmensdaten werden geprüft.');const prices=await loadSymbol(symbol,true);if(!prices)toast(symbol+': '+(marketLoadErrors[symbol]||'Kursdatenabruf fehlgeschlagen'),true);if(server.fmp){await loadFundamentals(symbol);await loadEvents(symbol);}else {render();toast('Für KGV, Unternehmenszahlen und Ergebnis-Termine muss FMP_API_KEY im Cloudflare-Worker eingerichtet sein.',true);}}
async function loadFundamentals(symbol){try{const res=await apiFetch('/api/fundamentals?symbol='+encodeURIComponent(symbol),{cache:'no-store'});const data=await res.json();if(!res.ok)throw Error(data.error||'Fundamentaldaten nicht verfügbar');if(!data.fundamentals)throw Error('Der Anbieter liefert keine Fundamentaldaten.');cache[symbol]={...(cache[symbol]||{}),symbol,fundamentals:{...data.fundamentals,retrievedAt:data.asof||new Date().toISOString()}};render();toast(symbol+': Fundamentaldaten aktualisiert.');return true;}catch(e){toast(symbol+': '+e.message,true);return false;}}
async function loadEvents(symbol){if(!server.connected||!server.fmp){toast('Für Ergebnistermine ist ein FMP-Zugang erforderlich. Hauptversammlungen separat verifizieren.',true);return;}try{const res=await apiFetch('/api/events?symbol='+encodeURIComponent(symbol),{cache:'no-store'}),data=await res.json();if(!res.ok)throw Error(data.error||'Kalenderabfrage fehlgeschlagen');marketEvents[symbol]=data;delete eventErrors[symbol];render();toast('Ereigniskalender geladen.')}catch(e){eventErrors[symbol]=e.message;render();toast(e.message,true);}}
function saveManualEvent(form){const d=Object.fromEntries(new FormData(form));if(!validTradingDate(d.date)&&d.date<today())throw Error('Termin muss heute oder in der Zukunft liegen.');if(!/^\d{4}-\d{2}-\d{2}$/.test(d.date)||!Number.isFinite(Date.parse(d.date))||new Date(d.date).toISOString().slice(0,10)!==d.date)throw Error('Ungültiges Kalenderdatum.');const symbol=validateTicker(d.symbol);if(isAlternativeAsset(symbol))throw Error('Ereignisse nur für Aktien erfassen.');const names={agm:'Hauptversammlung (manuell)',earnings:'Ergebnisbericht (manuell)',other:'Unternehmenstermin (manuell)'};if(!names[d.type])throw Error('Unbekannter Ereignistyp.');state.manualEvents.push({id:uid(),symbol,date:d.date,type:d.type,label:names[d.type],source:String(d.source||'').trim().slice(0,180)});persist();render();toast('Termin lokal gespeichert – nicht extern verifiziert.');}
function aiPanel(rec,a,f){return `<section class="panel panel-inner"><div class="panel-head"><div><div class="panel-title">KI-Gespräch zur ausgewählten Aktie</div><div class="panel-sub">Antworten auf Grundlage aktuell abgefragter Börsendaten</div></div><span class="card-status ${server.ai?'':'demo'}">${server.ai?'KI-SCHLÜSSEL EINGERICHTET':'NICHT VERBUNDEN'}</span></div>${aiText[selected]?`<div class="explainer" style="white-space:pre-wrap">${esc(aiText[selected])}</div>`:`<p class="explainer">Sobald du den Online-Server und den geschützten KI-API-Schlüssel eingerichtet hast, kann die KI deine Elliott-Zielzonen, Kennzahlen und Risiken erklären. Die Antwort wird serverseitig mit einem neuen Markt-Datenabruf abgeglichen.</p>`}<button class="btn btn-small ${server.ai?'btn-primary':''}" id="ask-ai" ${!server.ai||!a||rec?.demo?'disabled':''}>${server.ai?'Aktuelle KI-Auswertung erstellen':'Für KI echte Kurse und Online-API nötig'}</button><form id="form-ai-question" style="margin-top:14px"><div class="field"><label>Frage zur ausgewählten Aktie</label><textarea name="question" rows="3" maxlength="380" placeholder="Zum Beispiel: Welche Kursmarke würde das bullische Szenario widerlegen?" required></textarea></div><button class="btn btn-primary btn-small" type="submit" ${!server.ai||!a||rec?.demo?'disabled':''}>Frage an KI senden</button></form><span class="side-note">Nur Kursdaten, technische Heuristik und deine Frage werden übertragen. Keine Depotstückzahlen oder Einstandspreise. Prozent-Gewichtungen sind keine statistischen Eintrittswahrscheinlichkeiten.</span></section>`;}
function portfolioAiPanel(){const symbols=symbolsHeld().filter(x=>x!=='DEMO');const availability=symbols.slice(0,6);return `<section class="panel panel-inner"><div class="panel-head"><div><div class="panel-title">KI-Gespräch zu meinem Depot</div><div class="panel-sub">Depotübergreifende Chancen, Risiken und Elliott-Szenarien</div></div><span class="pill neutral">Bis zu 6 Positionen</span></div><p class="explainer">Die KI ruft für jedes ausgewählte Börsenkürzel neue Serverdaten ab. Ohne ausreichende Kursdaten wird keine vollständige Depotanalyse behauptet. Standardmäßig werden <strong>nur die Ticker</strong> übertragen, keine Stückzahlen oder Kaufpreise.</p><form id="form-portfolio-ai"><div class="field"><label>Depotpositionen auswählen</label><div class="check-grid">${availability.length?availability.map(sym=>`<label class="check-row"><input type="checkbox" name="symbols" value="${esc(sym)}" checked> ${esc(STOCK_NAMES[sym]||sym)} (${esc(sym)})</label>`).join(''):'<p class="side-note">Noch keine echten Depotpositionen eingetragen.</p>'}</div></div><div class="field"><label>Meine Frage zum Depot</label><textarea name="question" rows="3" maxlength="380" placeholder="Welche Titel sind technisch schwach und welche Risiken sind besonders relevant?" required></textarea></div><label class="check-row"><input type="checkbox" name="includePositions"> Stückzahlen und Einstandswerte ausdrücklich für diese Auswertung übertragen</label><button class="btn btn-primary btn-small" type="submit" ${!server.ai||!availability.length?'disabled':''}>Depot-KI befragen</button></form>${portfolioAiResult?`<div class="explainer" style="white-space:pre-wrap">${esc(portfolioAiResult)}</div>`:''}${portfolioAiError?`<p class="side-note">${esc(portfolioAiError)}</p>`:''}<p class="side-note">Benötigt Cloudflare-Worker ab 1.2 mit /api/portfolio-interpret und OpenAI-API. Die App allein aktiviert diese Serverfunktion nicht. Nicht als Anlageberatung zu verstehen.</p></section>`;}
function screenerPage(){const universe=[...new Set(Object.values(SECTORS).flat())];const selectedUniverse=sector==='Alle'?universe:SECTORS[sector];const list=selectedUniverse.filter(sym=>!screenerSearch||sym.toLowerCase().includes(screenerSearch.toLowerCase())||(STOCK_NAMES[sym]||'').toLowerCase().includes(screenerSearch.toLowerCase()));const ranked=list.map(sym=>({sym,rec:cache[sym],rank:ranking(cache[sym])})).sort((a,b)=>(b.rank?.score??-1)-(a.rank?.score??-1));return pageHead('IDEEN / MARKTUNIVERSUM','Markt-Screener','Vergleiche ein kuratiertes Aktienuniversum aus KI, Robotik, Cloud, Energie und Cannabis. Keine vollumfängliche Marktabdeckung.',`<button class="btn btn-ghost" id="refresh-screen">Universum laden</button><button class="btn btn-primary" id="export-screen">Ergebnisse exportieren</button>`)+banner()+`<div class="toolbar"><div class="segmented">${['Alle',...Object.keys(SECTORS)].map(s=>`<button data-sector="${s}" class="${sector===s?'active':''}">${s}</button>`).join('')}</div><input class="search-field toolbar-right" id="screen-search" placeholder="Ticker oder Name filtern…" value="${esc(screenerSearch)}" aria-label="Aktien durchsuchen"></div><div class="metric-grid">${metric('Universe Coverage',String(universe.length),'Vordefinierte Titel; kein Gesamtmarkt')}${metric('Mit Preisreihen',String(universe.filter(s=>technical(cache[s])).length),'Analysierbare Zeitreihen')}${metric('Fundamental bewertet',String(universe.filter(s=>fundamentals(cache[s])).length),'Nur bei Finanzdaten')}${metric('Vollständig verglichen',String(universe.filter(s=>ranking(cache[s])).length),'Score setzt beide Datenarten voraus')}</div><div class="market-ideas">${ranked.map(({sym,rec,rank})=>{const a=technical(rec),sect=Object.keys(SECTORS).find(s=>SECTORS[s].includes(sym));return `<div class="idea-card"><div class="top"><span class="tag">${esc(sect)}</span>${rank?`<span class="pill">${rank.score} / 100</span>`:'<span class="pill neutral">Nicht bewertet</span>'}</div><h3>${esc(STOCK_NAMES[sym]||sym)} <small class="muted">${sym}</small></h3><p>${a?'Aktuell '+trendLabel(a.trend).toLowerCase()+'. Technische Zonen und Kennzahlen verfügbar, soweit vom Anbieter geliefert.':'API-Daten fehlen. Keine künstliche Rangfolge oder Kursprognose.'}</p><div class="scores"><span>Markt <b>${a?trendLabel(a.trend):'—'}</b></span><span>KGV <b>${fundamentals(rec)?.pe!=null?fmt(fundamentals(rec).pe):'—'}</b></span></div><div class="btn-row"><button class="btn btn-small" data-detail="${sym}">Analysieren</button><button class="btn btn-small btn-ghost" data-watch="${sym}">${state.watchlist.some(w=>w.symbol===sym)?'✓ Merkliste':'+ Watchlist'}</button></div></div>`}).join('')}</div><div class="help-box" style="margin-top:20px"><h3>Scoring transparent statt KI-Hype</h3><p>Der experimentelle Vergleichsscore kombiniert 65 % verfügbare Fundamentalkennzahlen und 35 % Trend-Signale. Für alle fünf Fundamentalkriterien wird nur über vorhandene Werte gemittelt. Ein vergleichbarer institutioneller Gesamtscore, Analystenkonsens und automatisches Screening des gesamten Marktes sind noch nicht implementiert. Der Score ist keine Kaufempfehlung.</p></div>`;}
function alertsPage(){return pageHead('KURSÜBERWACHUNG','Kursalarme','Lege obere und untere Kursgrenzen oder konkrete Zonen fest. Auslösung nach eingehender Kursaktualisierung.',`<button class="btn btn-ghost" id="notifications-permission">Browser-Mitteilungen</button><button class="btn btn-primary" id="add-alert">+ Neuer Alarm</button>`)+banner()+`<div class="layout"><section class="panel"><div class="panel-inner"><div class="panel-head"><div><div class="panel-title">Aktive Überwachungen</div><div class="panel-sub">Bei Grenzeintritt, nicht bei jeder wiederholten Aktualisierung</div></div><span class="card-status">${state.alerts.filter(a=>a.enabled).length} aktiv</span></div></div>${state.alerts.length?state.alerts.map(a=>`<div class="alert-item"><div class="alert-dot ${a.enabled?'':'off'}"></div><div class="alert-detail"><b>${esc(a.symbol)} · ${esc(a.name||'Kursalarm')}</b><small>${a.type==='above'?'Kurs ≥ '+money(a.low,a.currency):a.type==='below'?'Kurs ≤ '+money(a.low,a.currency):'Kurszone '+rangeText([a.low,a.high],a.currency)}</small></div><span class="card-status">${a.enabled?'Aktiv':'Pausiert'}</span><button class="linkish" data-toggle-alert="${esc(a.id)}">${a.enabled?'Pause':'Start'}</button><button class="linkish neg" data-remove-alert="${esc(a.id)}">✕</button></div>`).join(''):'<div class="empty-state"><h3>Noch keine Alarme</h3><p>Lege beispielsweise für CGC einen Preisbereich an. Die App prüft ihn beim Laden neuer Kurse.</p><button class="btn btn-small" id="add-alert-empty">+ Alarm hinzufügen</button></div>'}</section><div class="stack"><section class="panel panel-inner"><div class="panel-head"><div class="panel-title">Alarm-Protokoll</div></div>${state.notifications.length?state.notifications.slice(0,10).map(n=>`<div class="data-row"><span>${esc(n.when)}<br><strong>${esc(n.symbol)}</strong></span><strong>${esc(n.text)}</strong></div>`).join(''):'<p class="explainer">Noch kein Alarmereignis erfasst.</p>'}<button class="btn btn-small btn-ghost" id="clear-history">Verlauf löschen</button></section><div class="help-box"><h3>Technische Grenze</h3><p>In dieser Webversion werden Alarme nur geprüft, wenn sie geöffnet ist und neue Daten eintreffen. Browser-Mitteilungen sind keine garantierten Hintergrund-Pushs. Für Überwachung bei geschlossenem Browser ist später ein geplanter Serverjob mit Push-Dienst erforderlich.</p></div>${cache.DEMO?`<section class="panel panel-inner"><div class="panel-head"><div class="panel-title">Demo-Alarm testen</div></div><p class="explainer">Ändere den künstlichen Testkurs und prüfe deinen DEMO-Alarm.</p><div class="btn-row"><button class="btn" id="demo-down">Demo −5 %</button><button class="btn" id="demo-up">Demo +5 %</button></div></section>`:''}</div></div>`;}
function helpPage(){return pageHead('SBRO STARTEN','Willkommen bei SBro Analyse','So nutzt du dein Depot und richtest später echte Markt- und KI-Daten ein.')+`<section class="panel panel-inner"><h2>1. Aktien im Depot erfassen</h2><p class="explainer">Öffne „Mein Depot“ → „Kauf erfassen“. Gib Börsenkürzel, Stückzahl, Datum, Kaufkurs, Handelswährung und gegebenenfalls Gebühren ein. Weitere Käufe derselben Aktie legst du einzeln an. Die Werte bleiben auf diesem iPhone gespeichert.</p><button class="btn btn-primary" data-page="portfolio">Mein Depot öffnen</button></section><section class="panel panel-inner" style="margin-top:16px"><h2>2. Die Onlinedaten verbinden</h2><p class="explainer">GitHub Pages hostet nur die Oberfläche. Für Bitcoin, Aktien, ISIN-/WKN-Suche und KI muss ein eigener HTTPS-API-Dienst bereitstehen. Wir haben dafür einen Cloudflare-Worker vorbereitet: <strong>1.</strong> Kostenlosen Cloudflare-Account anlegen (<a href="https://dash.cloudflare.com" target="_blank" rel="noopener noreferrer">Cloudflare öffnen</a>), <strong>2.</strong> den Code aus <code>backend/worker.js</code> als Worker veröffentlichen, <strong>3.</strong> gewünschte Anbieter-API-Schlüssel nur unter „Variables and Secrets“ hinterlegen, <strong>4.</strong> die HTTPS-Workeradresse bei „Datenquellen“ eintragen. Eine ausführliche Anleitung liegt im neuen ZIP-Paket. Mit <strong>„Bitcoin-Testabruf“</strong> prüfst du die Verbindung.</p><button class="btn" data-page="settings">Zur API-Einrichtung</button></section><section class="panel panel-inner" style="margin-top:16px"><h2>3. Analysieren & sichern</h2><p class="explainer">Nach erfolgreichem Kursabruf zeigt SBro Charts, bullische/bärische Elliott-Szenarien und Zielzonen. Die Prozentwerte sind heuristische Gewichte, keine gemessenen Trefferwahrscheinlichkeiten. Für Aktienkennzahlen wird ein FMP-Zugang benötigt; die KI-Anfrage nutzt zusätzlich einen OpenAI-API-Schlüssel auf dem Server.</p><p class="explainer"><strong>Wichtig:</strong> Depotstände sind auf jedem Gerät getrennt. Sichere deine Transaktionen unter „Datenquellen“ → „Backup herunterladen“ als JSON. Eine 8-Uhr-Push-Nachricht bei geschlossener App ist noch nicht verfügbar; dazu benötigen wir einen Hintergrunddienst.</p><button class="btn" data-page="settings">Backup & Einstellungen</button></section>`;}

function settingsPage(){return pageHead('EINRICHTUNG · ONLINE-DATEN','Datenquellen & Speicherung','Dein SBro-Cloudflare-Server ist bereits eingetragen. Du musst nur noch deinen privaten Zugangscode verwenden. Für KI und vollständige Fundamentaldaten sind zusätzliche Anbieterzugänge nötig.',`<button class="btn" data-page="help">? Erste Schritte</button>`)+banner()+`<div class="grid-2"><section class="panel panel-inner"><div class="panel-head"><div><div class="panel-title">1. Online-API verbinden</div><div class="panel-sub">Cloudflare-Server voreingestellt · nur privaten Zugangscode eintragen</div></div><span class="pill ${server.connected?'':'neutral'}">${server.connected?'Online-API erreichbar':'Noch nicht eingerichtet'}</span></div><form id="api-settings"><div class="field"><label>HTTPS-Adresse des Datenservers</label><input type="url" name="url" placeholder="https://sbro-analyse-api.steve-brombach.workers.dev" value="${esc(apiSettings.url)}" autocomplete="url"></div><div class="field"><label>Privater Zugangscode (falls auf dem Server eingerichtet)</label><input type="password" name="token" value="${esc(apiSettings.token)}" autocomplete="off" placeholder="Dein ACCESS_TOKEN"></div><p class="side-note">Hier <strong>keinen OpenAI-, Twelve-Data- oder FMP-API-Schlüssel</strong> eintragen! Diese gehören ausschließlich als Secret in den Cloud-Dienst. Der Zugangscode bleibt lokal auf diesem Gerät.</p><button class="btn btn-primary" type="submit">Verbindung speichern und prüfen</button> <button class="btn" type="button" id="check-server">Erneut prüfen</button> <button class="btn" type="button" id="test-btc">Bitcoin-Testabruf</button> <button class="btn btn-ghost btn-small" type="button" id="reset-api">Verbindung löschen</button></form><p class="side-note">Serverstatus: ${server.connected?'verbunden, echte Abrufe separat prüfen':lastConnectionError?'Fehler: '+esc(lastConnectionError):!apiSettings.token?'Zugangscode fehlt.':'Verbindung noch nicht bestätigt.'}</p></section><section class="panel panel-inner"><div class="panel-title">2. Welche Daten sind verfügbar?</div><div class="key-list"><div class="keyrow"><span>Bitcoin / Ethereum / Solana</span><strong>${server.crypto?'Kraken-Route bereit':'Ohne Online-Server nicht verfügbar'}</strong></div><div class="keyrow"><span>Aktien & Edelmetalle</span><strong>${server.twelve?'Twelve Data konfiguriert':'Twelve Data fehlt'}</strong></div><div class="keyrow"><span>ISIN, WKN, Namen</span><strong>${server.fmp?'FMP + OpenFIGI':'OpenFIGI bei verbundener API'}</strong></div><div class="keyrow"><span>KI-Analyse</span><strong>${server.ai?'OpenAI konfiguriert':'OpenAI / Zugangscode fehlt'}</strong></div></div><p class="explainer">„Konfiguriert“ bedeutet noch nicht „geprüft“. Eine echte Verbindung erkennst du erst, wenn ein Marktkurs mit Quelle, Währung und Zeitpunkt geladen wurde.</p><p class="side-note">Die Dateien <strong>backend/worker.js</strong> und <strong>ANLEITUNG_ONLINE_API.md</strong> im aktualisierten Paket erklären die Veröffentlichung. API-Schlüssel sind kosten- bzw. kontenabhängig.</p></section></div><section class="panel panel-inner" style="margin-top:16px"><div class="panel-title">3. Automatische Aktualisierung</div><form id="refresh-settings"><label class="check-row"><input type="checkbox" name="autoRefresh" ${state.settings.autoRefresh?'checked':''}> Geladene Kurse regelmäßig erneuern, <strong>solange SBro geöffnet ist</strong></label><div class="field"><label>Intervall</label><select name="refreshMinutes">${[5,15,30,60].map(v=>`<option value="${v}" ${state.settings.refreshMinutes===v?'selected':''}>${v} Minuten</option>`).join('')}</select></div><button class="btn btn-small btn-primary" type="submit">Speichern</button></form><p class="side-note">Bei geschlossener App wird noch kein Marktmonitoring ausgeführt. Die Datenanbieter können Limits und Verzögerungen haben.</p></section><section class="panel panel-inner" style="margin-top:16px"><div class="panel-title">Morgenbriefing · ${esc(state.settings.morningTime||'08:00')} (Europe/Berlin)</div><form id="briefing-settings" class="settings-report-form"><label class="check-row"><input type="checkbox" name="morningEnabled" ${state.settings.morningEnabled?'checked':''}> Bericht nur bei geöffneter App automatisch erstellen</label><div class="field"><label>Uhrzeit</label><input type="time" name="morningTime" value="${esc(state.settings.morningTime||'08:00')}" required></div><button type="submit" class="btn btn-small btn-primary">Uhrzeit speichern</button></form><p class="side-note">Push um eine frei einstellbare Uhrzeit trotz geschlossener App erfordert einen separaten Zeitplan- und Push-Dienst. Diese Version enthält ihn noch nicht.</p></section><section class="panel panel-inner" style="margin-top:16px"><div class="panel-title">Depotdaten auf diesem Gerät</div><p class="explainer">Deine Käufe, Alarme und Watchlist werden im Browser dieses iPhones gespeichert. Sie werden nicht automatisch auf Windows übertragen. Nutze regelmäßig JSON-Backups. Die API-Konfiguration wird aus Sicherheitsgründen nicht mit exportiert.</p><div class="btn-row"><button class="btn btn-small" id="export-json">Backup herunterladen</button><button class="btn btn-small btn-ghost" id="restore-json">Backup importieren</button><button class="btn btn-small btn-danger" id="reset-all">Lokale Depoteinträge löschen</button></div></section>`;}

function briefingDate(){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Berlin',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
function berlinTime(){return new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit',hourCycle:'h23',timeZone:'Europe/Berlin'}).format(new Date());}
function buildBriefing(notify=true){const positions=symbolsHeld().filter(s=>s!=='DEMO').map(position);const watch=state.watchlist.filter(w=>w.symbol!=='DEMO');const focus=positions.map(p=>{const t=technical(p.rec),risk=stress(p.rec);let notices=[];if(!p.rec){notices.push('Kein aktueller Kurs geladen – Datenquelle prüfen.');}else{if(p.pnlPct!=null&&p.pnlPct<=-10)notices.push('Position liegt mehr als 10 % unter Einstand – Risikogrenze prüfen.');if(t?.trend==='bear')notices.push('Technischer Trend bärisch – alternatives Szenario beobachten.');if(t&&p.price<t.invalidBull)notices.push('Bullisches Elliott-Szenario rechnerisch invalidiert.');if(risk?.risk>=2)notices.push('Finanzielle Stressindikatoren vorhanden.');}const soon=allEvents(p.symbol).filter(e=>e.date<=new Date(Date.now()+30*86400000).toISOString().slice(0,10));if(soon.length)notices.push(soon.length+' bevorstehende(r) Unternehmenstermin(e), Angaben/Quelle prüfen.');return {symbol:p.symbol,name:p.name,qty:p.qty,price:p.price,avg:p.avg,pnlPct:p.pnlPct,currency:p.currency,asof:p.rec?.asof||null,trend:t?.trend||'missing',targets:t?{bull:t.bTarget,bear:t.dTarget,invalid:t.invalidBull}:null,notices};});const ideas=watch.map(w=>{const r=cache[w.symbol],t=technical(r);return {symbol:w.symbol,name:w.name,asof:r?.asof||null,currency:r?.currency||'',trend:t?.trend||'missing',zone:t?.buy||null,near:t?cache[w.symbol].price>=t.buy[0]*.97&&cache[w.symbol].price<=t.buy[1]*1.03:false};}).filter(w=>w.zone&&w.trend==='bull').slice(0,6);const brief={id:uid(),date:briefingDate(),createdAt:new Date().toISOString(),focus,ideas,holdings:positions.length,unpriced:focus.filter(f=>f.price==null).length,alerts:focus.reduce((n,p)=>n+p.notices.length,0),api:!!server.twelve};state.briefings=[brief,...(state.briefings||[]).filter(x=>x.date!==brief.date)].slice(0,30);persist();if(notify)toast('Depot-Morgenbriefing erstellt. Marktdaten-Zeitstempel beachten.');return brief;}
function briefingPage(){const brief=state.briefings?.[0],date=brief?.date;const reportTime=state.settings.morningTime||'08:00';const todayReport=date===briefingDate();let html=pageHead('DEIN MORGENCHECK · '+esc(reportTime)+' UHR','Das Wichtigste, bevor der Tag startet.','Depotrisiken, Kursbewegungen und mögliche Watchlist-Chancen – sachlich, transparent und ohne automatische Handelsentscheidungen.',`<button class="btn" data-page="settings">Zeitplan einstellen</button><button class="btn btn-primary" id="create-briefing">Bericht jetzt erstellen</button>`)+banner()+`<div class="briefing-hero"><div><span class="briefing-kicker">☼ DEIN TÄGLICHER MARKTBLICK</span><h2>Ein klarer Blick auf dein Depot.</h2><p>${esc(reportTime)} Uhr · Zeitzone Europe/Berlin · ${state.settings.morningEnabled?'Automatik im geöffneten Browser aktiv':'Automatik ausgeschaltet'}</p></div><div class="briefing-hero-icon">${esc(reportTime.slice(0,2))}<span>:${esc(reportTime.slice(3))}</span></div></div>`;if(!brief)return html+`<section class="panel panel-inner"><h2 class="section-title">Noch kein Bericht vorhanden</h2><p class="explainer">Erfasse Aktien im Depot und klicke auf „Bericht jetzt erstellen“. Wenn Kursdaten vorhanden sind, erscheinen Risikosignale und Szenariozonen. Ohne API werden keine Kurse oder Chancen erfunden.</p><button class="btn btn-primary" id="create-briefing">Ersten Bericht erstellen</button></section>`;
html+=`<div class="status-note">${todayReport?'Bericht für heute':'Letzter gespeicherter Bericht'} · Erstellt: ${esc(new Date(brief.createdAt).toLocaleString('de-DE',{timeZone:'Europe/Berlin'}))} Uhr · ${brief.api?'API-Schlüssel konfiguriert':'Ohne aktive Kurs-API bei Erstellung'} · Zeitstempel je Aktie beachten</div><div class="metric-grid">${metric('Depotpositionen',brief.holdings,'Ohne Demo-Bestand')}${metric('Ohne verfügbare Kurse',brief.unpriced,'Keine Renditeberechnung ohne Marktdaten')}${metric('Prüfpunkte',brief.alerts,'Regelbasiert, keine Handlungsanweisung')}${metric('Watchlist-Ideen',brief.ideas.length,'Nur bei vorhandenen Daten')}</div>`;
html+=`<section class="panel panel-inner"><div class="panel-head"><div><div class="panel-title">Dein Depot · heute beachten</div><div class="panel-sub">Preis- und Trendsignale aus dem letzten geladenen Datenstand</div></div><button class="btn btn-small" id="refresh-briefing">Kurse laden & Bericht erneuern</button></div>${brief.focus.length?brief.focus.map(f=>`<div class="brief-row"><div class="brief-left"><b>${esc(f.symbol)} · ${esc(f.name)}</b><small>${fmt(f.qty,4)} Stück · Einstand ${money(f.avg,f.currency)} · Kurs ${money(f.price,f.currency)} · Stand ${esc(f.asof||'fehlt')}</small></div><div class="brief-right"><span class="${classPN(f.pnlPct)}">${pct(f.pnlPct)}</span><span class="pill ${f.trend==='bear'?'bear':f.trend==='missing'?'neutral':''}">${esc(trendLabel(f.trend))}</span></div><div class="brief-notes">${f.notices.length?f.notices.map(n=>`<span>• ${esc(n)}</span>`).join(''):'Keine zusätzlichen Warnsignale aus verfügbaren Regeln; keine Risikoentwarnung.'}${f.targets?`<small>Bullische Zielzone: ${rangeText(f.targets.bull,f.currency)} · Bärische Zielzone: ${rangeText(f.targets.bear,f.currency)}</small>`:''}</div></div>`).join(''):'<div class="empty-state">Noch keine echten Depotpositionen eingetragen.</div>'}</section>`;
html+=`<section class="panel panel-inner" style="margin-top:18px"><div class="panel-head"><div><div class="panel-title">Watchlist · mögliche Beobachtungszonen</div><div class="panel-sub">Rechnerische Elliott-Rücklaufzonen, keine sicheren Einstiegsempfehlungen</div></div></div>${brief.ideas.length?brief.ideas.map(i=>`<div class="data-row"><span><b>${esc(i.symbol)}</b> · ${esc(i.name)}<small> · Datenstand ${esc(i.asof||'unbekannt')}</small></span><strong>${i.near?'Kurs nahe Rücklaufzone':'Bullische Trendstruktur'} · ${rangeText(i.zone,i.currency)}</strong></div>`).join(''):'<p class="explainer">Noch keine Watchlist-Kandidaten mit belastbaren Kursreihen und bullischem Trend. Lade zuerst Marktdaten.</p>'}</section><p class="side-note">Dieser Report fasst regelbasierte Signale zusammen. Er ist weder ein KI-generierter individueller Anlageauftrag noch eine automatische Kauf- oder Verkaufsempfehlung. Ohne Hintergrundserver keine garantierte Zustellung um 08:00 Uhr.</p>`;return html;}
let morningRunning=false;async function maybeMorningBriefing(){if(morningRunning||!state.settings.morningEnabled||berlinTime()<(state.settings.morningTime||'08:00'))return;const date=briefingDate();if(state.briefings?.some(x=>x.date===date))return;morningRunning=true;try{if((server.twelve||server.crypto)&&symbolsHeld().some(s=>s!=='DEMO'))await refreshBatch(symbolsHeld().filter(s=>s!=='DEMO'),10);buildBriefing(false);if(page==='briefing')render();toast('Morgenbriefing für heute erstellt. Letzten Kursdatenstand beachten.');}finally{morningRunning=false;}}
let assetMatches=[];
async function assetSearch(){const box=$('asset-search'),holder=$('asset-results');if(!box||!holder)return;const q=box.value.trim();if(q.length<2){holder.innerHTML='<span class="muted">Bitte mindestens zwei Zeichen eingeben.</span>';return;}holder.innerHTML='<span class="muted">Suche läuft…</span>';let matches=[],remoteError='';if(server.connected&&(server.fmp||((server.openfigi||false)&&(/^[A-Z0-9]{6}$/i.test(q)||/^[A-Z]{2}[A-Z0-9]{9}[0-9]$/i.test(q))))){try{const res=await apiFetch('/api/search?q='+encodeURIComponent(q),{cache:'no-store'}),j=await res.json();if(!res.ok)throw Error(j.error||'Fehler bei der Suche');matches=Array.isArray(j.results)?j.results:[];}catch(e){remoteError=e.message;}}if(!matches.length&&!/^[A-Z]{2}[A-Z0-9]{9}[0-9]$/i.test(q)){matches=Object.entries(STOCK_NAMES).filter(([s,n])=>s!=='DEMO'&&(s.toLowerCase().includes(q.toLowerCase())||n.toLowerCase().includes(q.toLowerCase()))).slice(0,8).map(([symbol,name])=>({symbol,name,currency:'',isin:'',exchange:'',source:'Lokale Tickerliste'}));}assetMatches=matches;holder.innerHTML=matches.length?matches.slice(0,12).map((m,i)=>`<button type="button" class="asset-result" data-asset-choice="${i}"><span><b>${esc(m.symbol)}</b> · ${esc(m.name)}</span><small>${esc(m.isin||m.exchange||m.source||'Symbol')} ${m.currency?'· '+esc(m.currency):''}</small></button>`).join(''):`<div class="asset-noresults">${remoteError?'API-Suche: '+esc(remoteError):'Kein passender Treffer.'} ${/^[A-Z]{2}[A-Z0-9]{9}[0-9]$/i.test(q)?'ISIN-Auflösung benötigt OpenFIGI oder FMP mit erreichbarer API.':'Du kannst den Börsenticker weiterhin manuell eingeben.'}</div>`;}
function chooseAsset(index){const m=assetMatches[index];if(!m)return;const symbol=$('tx-symbol'),name=$('tx-name'),isin=$('tx-isin'),cur=$('tx-currency');if(symbol)symbol.value=m.symbol;if(name)name.value=m.name;if(isin)isin.value=m.isin||'';if(cur&&m.currency&&CURRENCIES.includes(m.currency))cur.value=m.currency;if($('asset-search'))$('asset-search').value=m.name+' · '+m.symbol;if($('asset-results'))$('asset-results').innerHTML='<div class="selected-asset">✓ '+esc(m.name)+' ('+esc(m.symbol)+') ausgewählt</div>';}
function drawCharts(){const root=$('chart-main');if(!root)return;const rec=cache[selected],t=technical(rec);if(!rec||!t){root.innerHTML=`<div class="empty-chart"><strong>Keine Kursreihe vorhanden</strong><p>Für ${esc(selected)} wurden noch keine historischen Kursdaten geladen. Verbinde Twelve Data und lade den Kursverlauf.</p><button class="btn btn-small" data-page="settings">Datenquelle konfigurieren</button></div>`;return;}
const all=rec.candles, n=({'1M':24,'3M':70,'1J':220,'3J':650}[timeRange]||220), bars=all.slice(-n),w=1000,h=440,L=35,R=102,T=23,B=46, plotW=w-L-R, plotH=h-T-B, visibleSpan=plotW*.75,bw=visibleSpan/(bars.length+0.2),futureX=L+visibleSpan+15;const zs=[t.bTarget[0],t.bTarget[1],t.dTarget[0],t.dTarget[1],t.buy[0],t.buy[1],...bars.map(b=>b.low),...bars.map(b=>b.high)], min=Math.min(...zs), max=Math.max(...zs),range=Math.max(max-min,.01), miny=Math.max(0,min-range*.10),maxy=max+range*.13;const Y=p=>T+(maxy-p)/(maxy-miny)*plotH,X=i=>L+(i+.5)*bw;
const grid=Array.from({length:6},(_,i)=>{const p=miny+(maxy-miny)*i/5,y=Y(p);return `<line x1="${L}" y1="${y.toFixed(1)}" x2="${w-R+7}" y2="${y.toFixed(1)}" stroke="#e5ecee" stroke-width="1" stroke-dasharray="3 5"/><text x="${w-R+14}" y="${(y+4).toFixed(1)}" fill="#647984" font-size="12">${esc(fmt(p,2))}</text>`}).join('');
const zone=(lo,hi,fill,edge,label)=>{const y1=Y(hi),y2=Y(lo);return `<rect x="${L}" y="${y1.toFixed(2)}" width="${plotW}" height="${Math.max(2,y2-y1).toFixed(2)}" fill="${fill}" opacity=".14"/><line x1="${L}" y1="${y1}" x2="${w-R}" y2="${y1}" stroke="${edge}" stroke-width="1" stroke-dasharray="5 6" opacity=".68"/><text x="${w-R-6}" y="${Math.max(T+10,y1-6)}" text-anchor="end" fill="${edge}" font-size="11">${label}</text>`};
let drawings=zone(t.bTarget[0],t.bTarget[1],'#b9822c','#b5791d','BULL. ZIEL')+zone(t.dTarget[0],t.dTarget[1],'#d87b79','#af6465','BÄR. ZIEL')+zone(t.buy[0],t.buy[1],'#7a9bd1','#6183bb','RÜCKLAUF / ENTRY');
const candlew=Math.max(1.3,Math.min(8,bw*.54));for(let i=0;i<bars.length;i++){const bar=bars[i],up=bar.close>=bar.open,col=up?'#169b8b':'#d87b79',x=X(i),top=Math.min(Y(bar.open),Y(bar.close)),body=Math.max(1.1,Math.abs(Y(bar.open)-Y(bar.close)));drawings+=`<line x1="${x}" x2="${x}" y1="${Y(bar.high)}" y2="${Y(bar.low)}" stroke="${col}" stroke-width="${Math.max(1.0,candlew*.18)}"/><rect x="${(x-candlew/2).toFixed(2)}" y="${top.toFixed(2)}" width="${candlew.toFixed(2)}" height="${body.toFixed(2)}" fill="${col}" rx=".8"/>`}
const baseIdx=all.length-bars.length, piv=t.pivots.filter(p=>p.i>=baseIdx), wave=piv.slice(-7);const waveLine=wave.map(p=>`${X(p.i-baseIdx).toFixed(2)},${Y(p.p).toFixed(2)}`).join(' ');if(wave.length>=2)drawings+=`<polyline points="${waveLine}" fill="none" stroke="#4f7180" stroke-width="1.8" stroke-dasharray="4 5" opacity=".76"/>`;wave.forEach((p,i)=>{const label=t.impulse&&i>=wave.length-6?['0','1','2','3','4','5'][i-(wave.length-6)]:'S'+(i+1);drawings+=`<circle cx="${X(p.i-baseIdx)}" cy="${Y(p.p)}" r="3.5" fill="#4f7280"/><text x="${X(p.i-baseIdx)+4}" y="${Y(p.p)-10}" fill="#3d6674" font-size="13" font-weight="700">${label}</text>`});
const current=bars.at(-1).close,lastX=X(bars.length-1),next1=futureX+46,next2=futureX+105;const pBull=[`${lastX},${Y(current)}`,`${next1},${Y((current+t.bTarget[0])/2)}`,`${next2},${Y((t.bTarget[0]+t.bTarget[1])/2)}`].join(' '),pBear=[`${lastX},${Y(current)}`,`${next1},${Y((current+t.dTarget[1])/2)}`,`${next2},${Y((t.dTarget[0]+t.dTarget[1])/2)}`].join(' ');drawings+=`<line x1="${futureX}" x2="${futureX}" y1="${T}" y2="${h-B}" stroke="#91a4ab" stroke-dasharray="4 5"/><text x="${futureX+9}" y="${T+13}" font-size="10" letter-spacing="1" fill="#6b8089">SZENARIEN</text><polyline points="${pBull}" fill="none" stroke="#b77f22" stroke-width="2.2" stroke-dasharray="6 5"/><polyline points="${pBear}" fill="none" stroke="#b96e6d" stroke-width="2.2" stroke-dasharray="6 5"/>`;
const priceY=Y(current);drawings+=`<line x1="${L}" y1="${priceY}" x2="${w-R}" y2="${priceY}" stroke="#427972" stroke-width="1" stroke-dasharray="2 4" opacity=".5"/><rect x="${w-R+8}" y="${priceY-12}" width="88" height="24" rx="5" fill="#daf2e9"/><text x="${w-R+52}" y="${priceY+4}" text-anchor="middle" font-size="12" font-weight="700" fill="#1e5a53">${esc(fmt(current))}</text>`;
let dates='';for(let i=0;i<5;i++){const idx=Math.round(i*(bars.length-1)/4);dates+=`<text x="${X(idx)}" y="${h-17}" text-anchor="middle" font-size="12" fill="#6b8089">${esc(dateDe(bars[idx].date))}</text>`}
root.innerHTML=`<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" role="img" aria-label="Kurschart ${esc(selected)} mit historischen Candlesticks, Fib-Zielzonen und Szenariolinien"><rect width="100%" height="100%" fill="#ffffff"/>${grid}${drawings}${dates}${rec.demo?'<text x="500" y="212" text-anchor="middle" font-size="63" opacity=".08" fill="#96aaa8" font-weight="750">DEMO / SIMULIERT</text>':''}</svg>`;}
function openModal(title,body){$('modal-title').textContent=title;$('modal-body').innerHTML=body;$('modal-backdrop').classList.remove('hidden');setTimeout(()=>{const inp=$('modal-body').querySelector('input');if(inp)inp.focus();},40);}
function closeModal(){$('modal-backdrop').classList.add('hidden');$('modal-body').innerHTML='';}
function txModal(symbol=''){const pos=position(symbol),c=pos.records.length?pos.currency:'USD';openModal('Aktie kaufen oder Verkauf eintragen',`<form id="form-transaction"><div class="asset-search-box"><div class="field"><label for="asset-search">Aktie suchen – Name, Ticker, ISIN oder WKN</label><div class="asset-search-controls"><input id="asset-search" placeholder="z. B. NVIDIA, NVDA oder US67066G1040" autocomplete="off" value="${esc(symbol==='DEMO'?'':symbol)}"><button class="btn btn-small" type="button" id="search-asset">Suchen</button></div><small>ISIN/WKN über OpenFIGI; Namen und Ticker online über FMP. Die lokale Tickerliste funktioniert ohne Server.</small></div><div id="asset-results" class="asset-results" role="status"></div></div><div class="form-grid"><div class="field"><label for="tx-symbol">Börsenkürzel *</label><input id="tx-symbol" name="symbol" placeholder="z. B. NVDA" required maxlength="28" autocomplete="off" value="${esc(symbol==='DEMO'?'':symbol)}"></div><div class="field"><label for="tx-name">Unternehmen</label><input id="tx-name" name="name" placeholder="z. B. NVIDIA Corporation" value="${esc(symbol==='DEMO'?'':pos.name)}"></div><div class="field"><label for="tx-isin">ISIN (optional)</label><input id="tx-isin" name="isin" placeholder="12-stellige ISIN" value="${esc(pos.records.find(x=>x.isin)?.isin||'')}" maxlength="12"><small>Eintragen, wenn du sie kennst; nicht zwingend.</small></div><div class="field"><label>Vorgang *</label><select name="type"><option value="buy">Kauf</option><option value="sell">Verkauf</option></select></div><div class="field"><label>Datum *</label><input name="date" type="date" max="${today()}" value="${today()}" required></div><div class="field"><label>Aktienanzahl *</label><input type="number" name="quantity" min="0.000001" step="any" placeholder="10" required></div><div class="field"><label>Kauf- oder Verkaufspreis pro Stück *</label><input type="number" name="price" min="0.000001" step="any" placeholder="100.00" required></div><div class="field"><label>Gebühren</label><input type="number" name="fees" min="0" step="any" value="0"></div><div class="field"><label>Währung des Handels</label><select id="tx-currency" name="currency">${CURRENCIES.map(q=>`<option ${c===q?'selected':''} value="${q}">${q}</option>`).join('')}</select></div></div><div class="help-box"><p><strong>Automatische Depotberechnung:</strong> Auch mehrere Käufe derselben Aktie werden einzeln gespeichert. Der offene Einstand wird nach FIFO berechnet. Handelswährung und Börsenplatz müssen zum Kursdaten-Symbol passen.</p></div><div class="modal-actions"><button type="button" class="btn" id="cancel-modal">Abbrechen</button><button class="btn btn-primary" type="submit">Im Depot speichern</button></div></form>`);}
function watchModal(){openModal('Aktie beobachten',`<form id="form-watch"><div class="asset-search-box"><div class="field"><label>Name, Ticker, ISIN oder WKN suchen</label><div class="asset-search-controls"><input id="asset-search" placeholder="z. B. NVIDIA oder ISIN" autocomplete="off"><button type="button" id="search-asset" class="btn btn-small">Suchen</button></div><small>ISIN/WKN über OpenFIGI und FMP, Namenssuche online über FMP; alternativ Ticker manuell eingeben.</small></div><div id="asset-results" class="asset-results"></div></div><div class="form-grid"><div class="field"><label>Ticker *</label><input id="tx-symbol" name="symbol" placeholder="NVDA" maxlength="28" required></div><div class="field"><label>Unternehmen</label><input id="tx-name" name="name" placeholder="NVIDIA"></div><div class="field"><label>ISIN (optional)</label><input id="tx-isin" name="isin" placeholder="US…" maxlength="12"></div></div><div class="modal-actions"><button type="button" class="btn" id="cancel-modal">Abbrechen</button><button type="submit" class="btn btn-primary">Zur Watchlist hinzufügen</button></div></form>`);}
function alarmModal(symbol=selected){const rec=cache[symbol],t=technical(rec);openModal('Zielzonenalarm einrichten',`<form id="form-alarm"><div class="form-grid"><div class="field"><label>Ticker *</label><input name="symbol" required maxlength="28" value="${esc(symbol==='DEMO'?'DEMO':symbol)}"></div><div class="field"><label>Alarmname</label><input name="name" value="${symbol==='DEMO'?'Demo-Zielbereich':'Meine Zielzone'}"></div><div class="field"><label>Alarmtyp</label><select name="type" id="alarm-type"><option value="above">Kurs erreicht / übersteigt Wert</option><option value="below">Kurs fällt auf / unter Wert</option><option value="zone">Kurs tritt in Zielzone ein</option></select></div><div class="field"><label>Währung</label><select name="currency">${CURRENCIES.map(c=>`<option value="${c}" ${c===(rec?.currency||'USD')?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label>Schwelle / Zone von *</label><input name="low" type="number" min="0" step="any" required placeholder="75.00" value="${Number.isFinite(t?.buy?.[0])?r2(t.buy[0]):''}"></div><div class="field"><label>Zone bis (bei Kurszone)</label><input name="high" type="number" min="0" step="any" placeholder="82.00" value="${Number.isFinite(t?.buy?.[1])?r2(t.buy[1]):''}"></div></div><div class="help-box"><p>Diese Alarme gelten nur für nachträglich eingehende Kursänderungen. Simulationskurse werden nur zur DEMO-Aktie genutzt; das Browserfenster muss für wiederkehrende Checks geöffnet sein.</p></div><div class="modal-actions"><button class="btn" type="button" id="cancel-modal">Abbrechen</button><button class="btn btn-primary" type="submit">Alarm speichern</button></div></form>`);}
function checkAlarms(symbol,price,prevPrice){if(!Number.isFinite(price))return;let fired=[];for(const a of state.alerts){if(!a.enabled||a.symbol!==symbol)continue;const rec=cache[symbol];if(rec?.currency&&rec.currency!==a.currency)continue;const active=a.type==='above'?price>=a.low:a.type==='below'?price<=a.low:price>=a.low&&price<=a.high;if(a.lastActive===undefined){const previous=Number.isFinite(prevPrice)?(a.type==='above'?prevPrice>=a.low:a.type==='below'?prevPrice<=a.low:prevPrice>=a.low&&prevPrice<=a.high):undefined;a.lastActive=previous===undefined?active:previous;if(previous===undefined)continue;}if(active&&!a.lastActive){fired.push(a);const msg=a.type==='zone'?`Zielzone ${fmt(a.low)}–${fmt(a.high)} erreicht`:`Kursgrenze ${fmt(a.low)} ${a.currency} erreicht`;state.notifications.unshift({id:uid(),symbol,when:new Date().toLocaleString('de-DE'),text:msg,price});toast(`🔔 ${symbol}: ${msg}`);if('Notification'in window&&Notification.permission==='granted'){try{new Notification(`SBro · ${symbol}`,{body:msg});}catch{}}}a.lastActive=active;}if(fired.length){state.notifications=state.notifications.slice(0,100);}persist();}
function demoMove(mult){const before=state.lastDemoPrice;state.lastDemoPrice=Math.max(.01,r2(before*mult));cache.DEMO=demoRecord();checkAlarms('DEMO',state.lastDemoPrice,before);persist();render();toast(`Demokurs auf ${money(state.lastDemoPrice,'USD')} gesetzt.`);}
function csvEscape(v){const x=String(v??'');return /[",\n\r;]/.test(x)?'"'+x.replace(/"/g,'""')+'"':x;}
function download(name,text,mime='text/plain;charset=utf-8'){const blob=new Blob([text],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function exportCSV(){const keys=['symbol','name','date','type','quantity','price','fees','currency'];const csv=[keys.join(';'),...state.transactions.map(t=>keys.map(k=>csvEscape(t[k])).join(';'))].join('\r\n');download('SBro_Transaktionen.csv','\ufeff'+csv,'text/csv;charset=utf-8');}
function exportJSON(){download('SBro_Analyse_Backup_'+today()+'.json',JSON.stringify(state,null,2),'application/json');}
function csvRows(str){const s=str.replace(/^\ufeff/,'');const first=s.split(/\r?\n/)[0]||'',delimiter=first.includes(';')?';':',';let rows=[],row=[],cell='',quoted=false;for(let i=0;i<s.length;i++){const ch=s[i];if(ch==='"'&&quoted&&s[i+1]==='"'){cell+='"';i++;}else if(ch==='"'){quoted=!quoted;}else if(ch===delimiter&&!quoted){row.push(cell);cell='';}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&s[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell='';}else cell+=ch;}row.push(cell);if(row.some(x=>x.trim()))rows.push(row);const keys=rows.shift()?.map(x=>x.trim().toLowerCase());if(!keys||!keys.includes('symbol')||!keys.includes('quantity')||!keys.includes('price'))throw Error('Spalten symbol, quantity und price fehlen.');return rows.map(r=>Object.fromEntries(keys.map((k,i)=>[k,(r[i]||'').trim()])));}
function chooseFile(ext,onload){const inp=document.createElement('input');inp.type='file';inp.accept=ext;inp.onchange=async()=>{const f=inp.files?.[0];if(!f)return;try{await onload(await f.text());}catch(e){toast(e.message,true);}};inp.click();}
function validateTicker(s){s=String(s||'').trim().toUpperCase();if(!/^[A-Z0-9.\-]{1,28}$/.test(s))throw Error('Ticker darf nur Buchstaben, Ziffern, Punkt und Bindestrich enthalten.');return s;}
function validTradingDate(date){if(typeof date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(date)||date>today())return false;const d=new Date(date+'T00:00:00Z');return Number.isFinite(d.getTime())&&d.toISOString().slice(0,10)===date;}
function validISIN(value){const isin=String(value||'').trim().toUpperCase();if(!/^[A-Z]{2}[A-Z0-9]{9}[0-9]$/.test(isin))return false;const digits=[...isin].map(ch=>/^[A-Z]$/.test(ch)?String(ch.charCodeAt(0)-55):ch).join('');let sum=0,double=false;for(let i=digits.length-1;i>=0;i--){let n=Number(digits[i]);if(double){n*=2;if(n>9)n-=9;}sum+=n;double=!double;}return sum%10===0;}
function addTransaction(t){const symbol=validateTicker(t.symbol),quantity=num(t.quantity),price=num(t.price),fees=num(t.fees||0),date=t.date,type=t.type||'buy',currency=(t.currency||'USD').toUpperCase();if(!validTradingDate(date))throw Error('Gültiges Kauf- bzw. Verkaufsdatum erforderlich.');if(!['buy','sell'].includes(type)||!Number.isFinite(quantity)||quantity<=0||!Number.isFinite(price)||price<=0||!Number.isFinite(fees)||fees<0)throw Error('Ungültige Mengen-, Kurs- oder Gebührenangaben.');if(!CURRENCIES.includes(currency))throw Error('Ungültige Handelswährung.');if(state.transactions.some(x=>x.symbol===symbol&&x.currency!==currency))throw Error('Für dasselbe Symbol wurden bereits Transaktionen in einer anderen Währung erfasst. Bitte eindeutige Börsenticker verwenden.');const isin=String(t.isin||'').trim().toUpperCase();if(isin&&!validISIN(isin))throw Error('ISIN ist ungültig (12 Stellen und Prüfziffer prüfen).');const existingIsins=[...new Set(state.transactions.filter(x=>x.symbol===symbol&&x.isin).map(x=>x.isin))];if(isin&&existingIsins.length&&existingIsins.some(x=>x!==isin))throw Error('Unter demselben Ticker liegt eine andere ISIN vor. Bitte die Zuordnung prüfen.');const next={id:uid(),symbol,name:String(t.name||STOCK_NAMES[symbol]||symbol).trim().slice(0,90),isin,date,type,quantity,price,fees,currency};const before=state.transactions.slice();state.transactions.push(next);try{const ordered=rowsFor(symbol);let q=0;for(const x of ordered){q+=x.type==='buy'?+x.quantity:-x.quantity;if(q< -1e-9)throw Error('Verkauf vor ausreichend vorhandenem Bestand. Bitte die Kauf- und Verkaufsdaten prüfen.');}}catch(e){state.transactions=before;throw e;}persist();return symbol;}
function importCSV(text){const parsed=csvRows(text);if(parsed.length>5000)throw Error('Zu viele Transaktionen (maximal 5000 pro Import).');const before=state.transactions.slice();let count=0;try{for(const x of parsed){addTransaction({...x,type:(x.type||'buy').toLowerCase(),date:x.date||today()});count++;}}catch(e){state.transactions=before;persist();throw Error('Import abgebrochen: '+e.message);}toast(`${count} Transaktionen importiert.`);render();}
async function restoreJSON(text){const obj=JSON.parse(text);if(!obj||!Array.isArray(obj.transactions)||!Array.isArray(obj.watchlist)||!Array.isArray(obj.alerts))throw Error('Kein gültiges SBro-Backup.');if(!confirm('Aktuelle lokale Depotdaten, Watchlist und Alarme durch Backup ersetzen?'))return;state={...initial(),...obj,version:VERSION};state.settings={...initial().settings,...(obj.settings||{})};state.briefings=Array.isArray(state.briefings)?state.briefings:[];state.notifications=Array.isArray(state.notifications)?state.notifications:[];persist();render();toast('Backup wiederhergestellt.');}
async function probeServer(show=false){if(!apiSettings.url){server={connected:false,twelve:false,stockFallback:false,fmp:false,ai:false,crypto:false,openfigi:false};if(show)toast('Keine Serveradresse eingetragen. Unter „Datenquellen“ die Cloudflare-HTTPS-Adresse eingeben.',true);render();return false;}try{const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);let res;try{res=await apiFetch('/api/status',{signal:controller.signal});}finally{clearTimeout(timer);}let data={};try{data=await res.json();}catch{throw Error('Server antwortet mit HTTP '+res.status+', aber nicht mit gültigem API-JSON. In Cloudflare den SBro-Worker-Code veröffentlichen.');}if(!res.ok){const reason=typeof data.error==='string'?data.error:'';if(res.status===401)throw Error('Cloudflare antwortet (HTTP 401), aber dein privater ACCESS_TOKEN fehlt oder stimmt nicht. Unter Datenquellen den Code aus Cloudflare eintragen.');if(res.status===403)throw Error('Cloudflare antwortet (HTTP 403), erlaubt aber diese Website-Adresse nicht. ALLOWED_ORIGIN muss https://u3050.github.io sein.');if(res.status===404)throw Error('Cloudflare antwortet (HTTP 404), aber /api/status fehlt. Prüfe die veröffentlichte Worker-Version.');throw Error('Cloudflare antwortet (HTTP '+res.status+'): '+(reason||'Serverkonfiguration beziehungsweise Worker-Logs prüfen.'));}if(data.connected!==true)throw Error('Der Server antwortet, meldet aber keine aktive SBro-API.');server=data;lastConnectionError='';if(show)toast('SBro-Server verbunden. Bitcoin und NVIDIA können jetzt einzeln auf Datenquellen geprüft werden.');render();return true;}catch(e){server={connected:false,twelve:false,stockFallback:false,fmp:false,ai:false,crypto:false,openfigi:false};let message=e.message||'Unbekannter Fehler';if(e.name==='AbortError')message='Der Server antwortet nicht innerhalb von 12 Sekunden. Worker-Adresse und Cloudflare-Status prüfen.';else if(e instanceof TypeError)message='Browser konnte den Server nicht erreichen. Cloudflare-Veröffentlichung, HTTPS-Adresse oder CORS (ALLOWED_ORIGIN) prüfen.';lastConnectionError=message;if(show)toast('Verbindungstest: '+message,true);render();return false;}}
const marketLoadErrors={};
async function loadSymbol(symbol,quiet=false){if(symbol==='DEMO'){cache.DEMO=demoRecord();return true;}if(!server.connected){if(!quiet)toast('Für dieses Instrument ist keine passende Kursdatenquelle verbunden. Bitte „Datenquellen“ prüfen.',true);return false;}try{const url='/api/market?symbol='+encodeURIComponent(symbol);const resp=await apiFetch(url,{cache:'no-store'});const js=await resp.json();if(!resp.ok)throw Error(js.error||'Abfrage fehlgeschlagen');if(!Array.isArray(js.candles)||!js.candles.length)throw Error('Keine historischen Kurse erhalten');const last=js.candles.at(-1),price=Number.isFinite(js.price)?js.price:last.close;if(!Number.isFinite(price)||price<=0)throw Error('Ungültige Kurswerte vom Anbieter');const old=cache[symbol];const candles=js.candles.map(x=>({date:x.date,open:+x.open,high:+x.high,low:+x.low,close:+x.close,volume:+x.volume||0}));if(candles.length<55||candles.some(x=>!/^\d{4}-\d{2}-\d{2}$/.test(x.date)||![x.open,x.high,x.low,x.close].every(v=>Number.isFinite(v)&&v>0)||x.high<Math.max(x.open,x.close)||x.low>Math.min(x.open,x.close))||candles.some((x,i)=>i&&x.date<=candles[i-1].date))throw Error('Ungültige oder zu kurze Kurszeitreihe');if(js.currency!=='USD'&&(['BTCUSD','ETHUSD','SOLUSD'].includes(symbol)))throw Error('Krypto-Währungspaare müssen in USD geliefert werden');if(Math.abs(candles.at(-1).close-price)>price*0.000001)throw Error('Datenquelle: Kurs und letzte Chartkerze weichen ab – Analyse vorsichtshalber gesperrt');const normalized={...js,symbol,price,candles,provider:js.provider||'Unbekannt'};cache[symbol]=normalized;checkAlarms(symbol,price,old?.price);delete marketLoadErrors[symbol];if(!quiet)toast(`${symbol} aktualisiert · ${normalized.asof||'Marktdatenanbieter'}`);return true;}catch(e){marketLoadErrors[symbol]=String(e?.message||'Unbekannter Kursdatenfehler');if(!quiet)toast(`${symbol}: ${marketLoadErrors[symbol]}`,true);return false;}}
async function refreshBatch(symbols,max=18,quiet=false){if(!server.connected){if(!quiet){setPage('settings');toast('Für echte Kurse zuerst den Online-API-Server verbinden.',true);}return;}if(busy){if(!quiet)toast('Datenabfrage läuft bereits.');return;}busy=true;let done=0,failed=0,list=[...new Set(symbols)].filter(s=>s!=='DEMO').slice(0,max);if(!quiet)toast(`Kursaktualisierung gestartet (${list.length} Titel).`);for(const symbol of list){const ok=await loadSymbol(symbol,true);if(ok)done++;else failed++;}busy=false;render();const details=failed?list.filter(symbol=>marketLoadErrors[symbol]).map(symbol=>`${symbol}: ${marketLoadErrors[symbol]}`).slice(0,3).join(' | '):'';if(!quiet)toast(`${done} Kursreihen geladen${failed?', '+failed+' fehlgeschlagen':''}.${details?' '+details:''}`,failed>0&&done===0);}
async function requestPortfolioAI(form){const dat=new FormData(form);const symbols=[...new Set(dat.getAll('symbols').map(x=>String(x).toUpperCase()))].slice(0,6);const question=String(dat.get('question')||'').trim().slice(0,380);if(!server.ai)throw Error('KI-API noch nicht aktiviert.');if(!symbols.length||!question)throw Error('Mindestens eine Depotposition und eine Frage auswählen.');const held=symbolsHeld();if(symbols.some(x=>!held.includes(x)))throw Error('Nur Titel aus deinem Depot sind für diese Anfrage zugelassen.');const includePositions=dat.has('includePositions');const positions=symbols.map(symbol=>{const p=position(symbol);return {symbol,...(includePositions?{quantity:p.qty,cost:p.cost,currency:p.currency}: {})};});portfolioAiError='';toast('Depot-KI wird angefragt – Marktdaten werden serverseitig geprüft.');try{const response=await apiFetch('/api/portfolio-interpret',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({positions,question})});const result=await response.json().catch(()=>({}));if(!response.ok)throw Error(response.status===404?'Cloudflare-Worker muss auf Version 1.2 aktualisiert werden.':result.error||'Depot-KI derzeit nicht verfügbar.');portfolioAiResult=String(result.text||'Keine Antwort.').slice(0,12000)+'\n\nDatenquellen: '+(result.sources||[]).map(x=>x.symbol+': '+x.provider+' · '+x.asof).join('; ');portfolioAiError='';render();toast('Depot-Auswertung erstellt.');}catch(e){portfolioAiError=e.message;render();toast('Depot-KI: '+e.message,true);}}
async function requestAI(question=''){const rec=cache[selected],t=technical(rec),f=fundamentals(rec);if(!server.ai||!t){toast('KI-Server oder Kursanalyse nicht verfügbar.',true);return;}const data={symbol:selected,question,events:allEvents(selected),asof:rec.asof,currency:rec.currency,quoteKind:rec.quoteKind,technical:{trend:t.trend,sma20:t.avg20,sma50:t.avg50,momentum20d:t.mom,bullishTarget:t.bTarget,bearishTarget:t.dTarget,buyZone:t.buy,bullishInvalidation:t.invalidBull,bearishInvalidation:t.invalidBear,impulseCandidate:t.impulse,swings:t.pivots.length},fundamentals:f,financialStress:stress(rec),source:{provider:rec.provider,reportDate:rec.fundamentals?.reportDate||null}};try{toast('KI-Analyse wird erstellt.');const res=await apiFetch('/api/interpret',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const js=await res.json();if(!res.ok)throw Error(js.error||'KI-Servicefehler');aiText[selected]=(js.text||'Keine Antwort erhalten.')+'\n\nDatenquelle: '+(js.marketProvider||'unbekannt')+' · Stand: '+(js.marketAsOf||'unbekannt')+' · Trend- und Elliott-Zonen: serverseitige Heuristik.';render();toast('KI-Interpretation erstellt.');}catch(e){toast('KI-Anfrage fehlgeschlagen: '+e.message,true);}}
async function askNotify(){if(!('Notification'in window)){toast('Browser-Mitteilungen in dieser Umgebung nicht verfügbar.',true);return;}try{const p=await Notification.requestPermission();toast(p==='granted'?'Browser-Mitteilungen erlaubt.':'Browser-Mitteilungen nicht erlaubt.',p!=='granted');}catch(e){toast('Browser-Mitteilungen nur unter localhost oder HTTPS.',true);}}
function openDetail(s){selected=s;setPage('analyse');if(s!=='DEMO'&&server.connected&&state.settings.autoRefresh&&!cache[s])refreshBatch([s],1,true);}
function addToWatch(s){if(state.watchlist.some(w=>w.symbol===s)){toast(`${s} steht bereits auf der Watchlist.`);return;}state.watchlist.push({symbol:s,name:STOCK_NAMES[s]||s});persist();render();toast(`${s} zur Watchlist hinzugefügt.`);}
function addTradeFromForm(form){const dat=Object.fromEntries(new FormData(form));const symbol=addTransaction(dat);closeModal();selected=symbol;setPage('portfolio');toast('Transaktion für '+symbol+' gespeichert.');}
function addAlertFromForm(form){const dat=Object.fromEntries(new FormData(form)),symbol=validateTicker(dat.symbol),low=num(dat.low),high=num(dat.high);if(!Number.isFinite(low)||low<=0)throw Error('Gültige Alarmschwelle erforderlich.');if(dat.type==='zone'&&(!Number.isFinite(high)||high<=low))throw Error('Obere Grenze der Kurszone muss größer sein.');const a={id:uid(),symbol,name:(dat.name||'Kursalarm').slice(0,100),type:dat.type,low,high:dat.type==='zone'?high:null,currency:dat.currency,enabled:true};const current=cache[symbol];if(Number.isFinite(current?.price)&&current?.currency===dat.currency){a.lastActive=dat.type==='above'?current.price>=low:dat.type==='below'?current.price<=low:current.price>=low&&current.price<=high;}state.alerts.push(a);persist();closeModal();setPage('alerts');toast('Kursalarm angelegt. Bei der nächsten Kursmeldung wird der Ausgangszustand bestimmt.');}
function handleClick(event){const btn=event.target.closest('button');if(!btn)return;if(btn.dataset.assetChoice!==undefined){chooseAsset(Number(btn.dataset.assetChoice));return;}const p=btn.dataset.page;if(p){setPage(p);return;}if(btn.dataset.range){timeRange=btn.dataset.range;render();return;}if(btn.dataset.detail){openDetail(btn.dataset.detail);return;}if(btn.dataset.marketLoad){selected=btn.dataset.marketLoad;setPage('analyse');refreshBatch([selected],1);return;}if(btn.dataset.customTrade){txModal(btn.dataset.customTrade);return;}if(btn.dataset.sector){sector=btn.dataset.sector;render();return;}if(btn.dataset.watch){addToWatch(btn.dataset.watch);return;}if(btn.dataset.removeWatch){if(!confirm(btn.dataset.removeWatch+' von Watchlist entfernen?'))return;state.watchlist=state.watchlist.filter(w=>w.symbol!==btn.dataset.removeWatch);persist();render();return;}if(btn.dataset.toggleAlert){const a=state.alerts.find(x=>x.id===btn.dataset.toggleAlert);if(a){a.enabled=!a.enabled;a.lastActive=undefined;persist();render();}return;}if(btn.dataset.removeAlert){if(confirm('Kursalarm wirklich entfernen?')){state.alerts=state.alerts.filter(x=>x.id!==btn.dataset.removeAlert);persist();render();}return;}if(btn.dataset.removeTx){if(confirm('Transaktion löschen? Das kann FIFO-Bestände ändern.')){const old=state.transactions.slice();state.transactions=state.transactions.filter(x=>x.id!==btn.dataset.removeTx);try{for(const sym of [...new Set(state.transactions.map(t=>t.symbol))]){let q=0;for(const x of rowsFor(sym)){q+=x.type==='buy'?+x.quantity:-x.quantity;if(q<-1e-9)throw Error('Ein Kauf wird für spätere Verkäufe benötigt.');}}}catch(e){state.transactions=old;toast('Nicht entfernt: '+e.message,true);return;}persist();render();}return;}
const id=btn.id;switch(id){case'mobile-menu':$('sidebar').classList.toggle('open');break;case'global-add':case'add-transaction':txModal();break;case'search-asset':assetSearch();break;case'create-briefing':buildBriefing();render();break;case'refresh-briefing':(async()=>{await refreshBatch(symbolsHeld().filter(s=>s!=='DEMO'),10);buildBriefing();render();})();break;case'add-tx-current':case'add-tx-current-2':txModal(selected);break;case'add-watch':watchModal();break;case'add-alert':case'add-alert-empty':case'add-alert-for':alarmModal(selected);break;case'modal-close':case'cancel-modal':closeModal();break;case'refresh-btn':case'refresh-market':refreshBatch(allTracked(),15);break;case'refresh-one':refreshBatch([selected],1);break;case'refresh-company':refreshCompanyAnalysis();break;case'refresh-watch':refreshBatch(state.watchlist.map(x=>x.symbol));break;case'refresh-screen':refreshBatch(sector==='Alle'?Object.values(SECTORS).flat():SECTORS[sector],18);break;case'check-server':probeServer(true);break;case'reset-api':if(confirm('Online-API-Adresse und Zugangscode auf diesem Gerät löschen?')){saveApiSettings({url:'',token:''});render();toast('API-Verbindung lokal gelöscht.');}break;case'test-btc':(async()=>{if(await probeServer(false)){if(await loadSymbol('BTCUSD',false)){selected='BTCUSD';setPage('analyse');}}else toast('Online-API nicht erreichbar. Bitte zuerst Datenquellen einrichten.',true);})();break;case'import-csv':chooseFile('.csv,text/csv',importCSV);break;case'export-csv':exportCSV();break;case'export-json':exportJSON();break;case'restore-json':chooseFile('.json,application/json',restoreJSON);break;case'export-screen':{const curr=(sector==='Alle'?[...new Set(Object.values(SECTORS).flat())]:SECTORS[sector]);const csv=['symbol;name;sector;lastprice;currency;trend;score;pe',...curr.map(sym=>[sym,STOCK_NAMES[sym],Object.keys(SECTORS).find(s=>SECTORS[s].includes(sym)),cache[sym]?.price??'',cache[sym]?.currency||'',technical(cache[sym])?.trend||'',ranking(cache[sym])?.score??'',fundamentals(cache[sym])?.pe??''].map(csvEscape).join(';'))].join('\r\n');download('SBro_Screener.csv','\ufeff'+csv,'text/csv;charset=utf-8');break;}case'remove-demo':if(confirm('Alle Musterkäufe für DEMO entfernen?')){state.transactions=state.transactions.filter(t=>!t.demo);persist();render();toast('Demodepot entfernt.');}break;case'reset-all':if(confirm('ACHTUNG: Alle lokalen Transaktionen, Watchlist und Alarme werden unwiderruflich gelöscht. Fortfahren?')){state={...initial(),transactions:[],watchlist:[],alerts:[],notifications:[],manualEvents:[]};persist();selected='DEMO';render();toast('Lokale Daten zurückgesetzt.');}break;case'notifications-permission':askNotify();break;case'clear-history':state.notifications=[];persist();render();break;case'demo-up':demoMove(1.05);break;case'demo-down':demoMove(.95);break;case'ask-ai':requestAI();break;case'load-events':loadEvents(selected);break;}}
async function handleSubmit(event){const form=event.target;if(!form?.id)return;event.preventDefault();try{switch(form.id){case'form-transaction':addTradeFromForm(form);break;case'form-watch':{const dat=Object.fromEntries(new FormData(form)),s=validateTicker(dat.symbol);if(!state.watchlist.some(x=>x.symbol===s)){state.watchlist.push({symbol:s,name:(dat.name||STOCK_NAMES[s]||s).slice(0,90),isin:String(dat.isin||'').toUpperCase()});persist();}closeModal();setPage('watchlist');toast(s+' auf Watchlist.');break;}case'form-alarm':addAlertFromForm(form);break;case'form-event':saveManualEvent(form);break;case'form-portfolio-ai':await requestPortfolioAI(form);break;case'form-ai-question':{const q=String(new FormData(form).get('question')||'').trim();if(!q)throw Error('Bitte eine konkrete Frage eingeben.');await requestAI(q);break;}case'briefing-settings':{const dat=Object.fromEntries(new FormData(form));if(!/^(?:[01]\d|2[0-3]):[0-5]\d$/.test(dat.morningTime||''))throw Error('Bitte eine gültige Uhrzeit eingeben.');state.settings.morningEnabled=!!dat.morningEnabled;state.settings.morningTime=dat.morningTime;persist();render();toast('Morgenbriefing-Uhrzeit gespeichert.');break;}case'api-settings':{const dat=Object.fromEntries(new FormData(form));saveApiSettings(dat);await probeServer(true);break;}case'refresh-settings':{const dat=Object.fromEntries(new FormData(form));state.settings.autoRefresh=!!dat.autoRefresh;state.settings.refreshMinutes=Math.max(5,+dat.refreshMinutes||15);persist();render();toast('Auto-Aktualisierung gespeichert.');break;}}}catch(e){toast(e.message,true);}}
document.addEventListener('click',handleClick);document.addEventListener('submit',handleSubmit);document.addEventListener('change',e=>{if(e.target.id==='analyse-stock'){selected=e.target.value;render();}});document.addEventListener('input',e=>{if(e.target.id==='screen-search'){screenerSearch=e.target.value;const start=e.target.selectionStart;const el=e.target;render();const input=$('screen-search');input?.focus();input?.setSelectionRange(start,start);}});$('modal-backdrop').addEventListener('click',e=>{if(e.target.id==='modal-backdrop')closeModal();});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});
let lastAuto=0;
function trackedForUpdate(){return [...new Set([...symbolsHeld(),...state.watchlist.map(w=>w.symbol)])].filter(symbol=>symbol!=='DEMO').slice(0,15);}
async function autoLoadTracked(force=false){if(!state.settings.autoRefresh||!server.connected||busy||document.visibilityState==='hidden')return;const wait=Math.max(5,Number(state.settings.refreshMinutes)||15)*60000;if(!force&&Date.now()-lastAuto<wait)return;const tracked=trackedForUpdate();if(!tracked.length)return;lastAuto=Date.now();await refreshBatch(tracked,15,true);}
setInterval(()=>autoLoadTracked(),60000);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')autoLoadTracked();});
window.addEventListener('online',()=>{if(server.connected)autoLoadTracked();else probeServer(false).then(ok=>{if(ok)autoLoadTracked(true);});});
render();probeServer(false).then(async ok=>{if(ok)await autoLoadTracked(true);maybeMorningBriefing();});setInterval(maybeMorningBriefing,60*1000);